1	/**
2	 * name.com API v4 client (reseller). Auth: HTTP Basic (username:token).
3	 * Production: https://api.name.com  ·  Dev/sandbox: https://api.dev.name.com
4	 */
5	
6	import { SANDBOX } from "./sandbox";
7	import { getSettingInt } from "./settings";
8	
9	export function registrarConfigured(): boolean {
10	  return !!(process.env.NAMECOM_USERNAME && process.env.NAMECOM_TOKEN);
11	}
12	
13	/**
14	 * Thrown at the registrar HTTP boundary (`nc()` below) instead of a plain
15	 * `Error`, so every catch site up the call chain can show a customer a safe,
16	 * registrar-name-free message while still keeping the real failure for ops.
17	 *
18	 * `message` (inherited) stays the RAW text for anything that logs `e.message`
19	 * without checking `instanceof` — `rawMessage` is the same value under an
20	 * explicit name for call sites that DO check. `customerMessage` is the only
21	 * one of the three ever allowed in front of a customer.
22	 *
23	 * The real production incident this exists for: a registrar 402 ("Payment
24	 * failed") was shown to a customer verbatim, registrar name included, because
25	 * every catch site just did `{ error: String(e.message) }`.
26	 */
27	export class RegistrarError extends Error {
28	  readonly registrarId: string;
29	  readonly rawMessage: string;
30	  readonly customerMessage: string;
31	
32	  constructor(registrarId: string, rawMessage: string) {
33	    super(rawMessage);
34	    this.name = "RegistrarError";
35	    this.registrarId = registrarId;
36	    this.rawMessage = rawMessage;
37	    this.customerMessage = classifyRegistrarFailure(rawMessage);
38	  }
39	}
40	
41	const PAYMENT_FAILURE_RE = /payment|balance|insufficient|declin|charge/i;
42	
43	/** Generic fallback — hedges "no charge" rather than asserting it, since not every call site is a payment. */
44	const GENERIC_CUSTOMER_MESSAGE =
45	  "Something went wrong on our end completing this request. No charge was made if this was a payment action; please try again or contact support.";
46	
47	const PAYMENT_CUSTOMER_MESSAGE =
48	  "We couldn't complete this right now — no charge was made. Please try again or contact support.";
49	
50	/** Pattern-match a raw registrar error into a customer-safe category. Never echoes `raw`. */
51	function classifyRegistrarFailure(raw: string): string {
52	  return PAYMENT_FAILURE_RE.test(raw) ? PAYMENT_CUSTOMER_MESSAGE : GENERIC_CUSTOMER_MESSAGE;
53	}
54	
55	/**
56	 * Registrar-safe message for any caught error: `customerMessage` when it's a
57	 * `RegistrarError`, otherwise the same raw-message-sliced behavior every catch
58	 * site already used. Centralizing this means every call site that reads a
59	 * caught registrar failure gets the fix by importing this instead of
60	 * hand-rolling `String(e?.message ?? e)`.
61	 *
62	 * Also logs `rawMessage` + `registrarId` server-side (console.error, same
63	 * mechanism this module already uses elsewhere) so a real failure is still
64	 * diagnosable from the logs even though the customer never sees it — most of
65	 * the ~15 call sites this replaces had no per-error logging of their own to
66	 * hook into, so this is the one place that can guarantee it happens.
67	 */
68	export function registrarSafeMessage(e: unknown): string {
69	  if (e instanceof RegistrarError) {
70	    console.error(`[registrar:${e.registrarId}] ${e.rawMessage}`);
71	    return e.customerMessage;
72	  }
73	  return String(e instanceof Error ? e.message : e).slice(0, 200);
74	}
75	
76	/**
77	 * Inbound transfers additionally work in SANDBOX (staging) with synthetic
78	 * results, so the whole transfer-in flow — quote, submit, poll, cancel — can be
79	 * exercised end to end without touching the registrar or a real domain.
80	 */
81	export function transfersAvailable(): boolean {
82	  return SANDBOX || registrarConfigured();
83	}
84	
85	function baseUrl(): string {
86	  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
87	}
88	
89	function authHeader(): string {
90	  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
91	  return "Basic " + Buffer.from(raw).toString("base64");
92	}
93	
94	async function nc(
95	  method: string,
96	  path: string,
97	  body?: unknown,
98	  opts?: { nullOn404?: boolean }
99	): Promise<any> {
100	  if (!registrarConfigured()) throw new RegistrarError("namecom", "registrar is not configured");
101	  const res = await fetch(`${baseUrl()}${path}`, {
102	    method,
103	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
104	    body: body ? JSON.stringify(body) : undefined,
105	    signal: AbortSignal.timeout(30_000),
106	  });
107	  const text = await res.text();
108	  let json: any = {};
109	  try {
110	    json = text ? JSON.parse(text) : {};
111	  } catch {
112	    /* non-JSON error body */
113	  }
114	  if (!res.ok) {
115	    // Some callers treat "absent" as a normal answer (e.g. polling a transfer
116	    // that has already dropped off the registrar's list) — let them opt in to a
117	    // null instead of an exception rather than string-matching an error message.
118	    if (opts?.nullOn404 && res.status === 404) return null;
119	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
120	    throw new RegistrarError("namecom", msg);
121	  }
122	  return json;
123	}
124	
125	const dollarsToCents = (d: number | undefined) => (d === undefined ? null : Math.round(d * 100));
126	
127	/** Fallback markup when no admin setting is saved. Matches the old hardcoded value. */
128	const DEFAULT_MARKUP_PCT = 25;
129	
130	/**
131	 * Platform markup over the registrar's cost, as a percentage.
132	 *
133	 * MONEY BUG (fixed 2026-07-26): Settings → Domains writes `domain_markup_percent`
134	 * and displays it, but NOTHING read it — the only references were the stored
135	 * default, the save whitelist, and the admin input itself. Meanwhile this function
136	 * read `DOMAIN_MARKUP_PCT`, which is not set in `.env`, so every domain price
137	 * silently carried the hardcoded 25%. The panel therefore showed an operator **0%**
138	 * while customers were charged **25%**, and editing the field changed nothing.
139	 *
140	 * The admin setting is now the source of truth, with the env var as the fallback so
141	 * an operator who had set it keeps their behaviour. The stored default is corrected
142	 * from "0" to 25 so the panel states what is genuinely applied — displaying 0% while
143	 * charging 25% is precisely the class of untruth this codebase keeps producing.
144	 *
145	 * Safe to change now: zero domains have been sold and the setting had never been
146	 * saved, so no customer's price moves as a result of this fix.
147	 *
148	 * Async because it reads a setting. Callers resolve it ONCE and pass it into
149	 * `retailCents`, which stays pure so the arithmetic is trivially checkable.
150	 */
151	export async function domainMarkupPct(): Promise<number> {
152	  const envDefault = Number(process.env.DOMAIN_MARKUP_PCT ?? DEFAULT_MARKUP_PCT);
153	  const pct = await getSettingInt("domain_markup_percent", envDefault);
154	  // Clamp: a free-text admin field that multiplies every domain price. A stray
155	  // keystroke must not be able to bill a customer 5000% of cost.
156	  return Math.min(Math.max(Number.isFinite(pct) ? pct : envDefault, 0), 500);
157	}
158	
159	/** Retail (customer) price for a registrar cost at `pct` markup. Pure. */
160	export function retailCents(costCents: number | null, pct: number): number | null {
161	  if (costCents === null) return null;
162	  return Math.round(costCents * (1 + pct / 100));
163	}
164	
165	export type DomainCheck = {
166	  domain: string;
167	  available: boolean;
168	  premium: boolean;
169	  priceCents: number | null; // RETAIL — what the customer pays (per year)
170	  costCents: number | null; // registrar cost (per year)
171	  renewCents: number | null; // RETAIL renewal price
172	};
173	
174	export async function checkDomains(domains: string[]): Promise<DomainCheck[]> {
175	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: domains });
176	  // Resolved ONCE for the whole batch: one settings read, and every price in a
177	  // single response is guaranteed to use the same markup.
178	  const pct = await domainMarkupPct();
179	  return (json.results ?? []).map((r: any) => {
180	    const cost = dollarsToCents(r.purchasePrice);
181	    const renewCost = dollarsToCents(r.renewalPrice ?? r.purchasePrice);
182	    return {
183	      domain: r.domainName,
184	      available: r.purchasable === true,
185	      premium: r.premium === true,
186	      priceCents: retailCents(cost, pct),
187	      costCents: cost,
188	      renewCents: retailCents(renewCost, pct),
189	    };
190	  });
191	}
192	
193	export type RegistrantContact = {
194	  firstName: string;
195	  lastName: string;
196	  address1: string;
197	  city: string;
198	  stateProvince: string;
199	  postalCode: string;
200	  country: string; // ISO-2
201	  phone: string; // +NN.NNNNNNNNNN
202	  email: string;
203	};
204	
205	function ncContact(c: RegistrantContact) {
206	  return {
207	    firstName: c.firstName,
208	    lastName: c.lastName,
209	    address1: c.address1,
210	    city: c.city,
211	    state: c.stateProvince,
212	    zip: c.postalCode,
213	    country: c.country,
214	    phone: c.phone,
215	    email: c.email,
216	  };
217	}
218	
219	/**
220	 * name.com's OWN auto-renew flag on the domain resource — entirely separate
221	 * from this platform's `Domain.autoRenew` column, and NOT settable on the
222	 * CreateDomain request itself (confirmed against name.com's own API docs).
223	 * Real risk found live (2026-08-29): if name.com's own default for an
224	 * API-registered domain is enabled, name.com can independently renew (and
225	 * charge NXEON'S reseller account, not the customer) on ITS OWN schedule —
226	 * regardless of what the customer chose here, including a domain they
227	 * explicitly turned auto-renew off for, or one whose owner has no wallet
228	 * funds. Disabling it after every register/renew makes
229	 * worker/billing.ts's domainAutoRenewSweep the ONLY thing that ever
230	 * initiates a renewal. Best-effort: must never fail a registration/renewal
231	 * that already succeeded and was already charged — a dangling
232	 * autorenew-enabled domain is a real ops risk to catch via this log line,
233	 * not a reason to unwind money that already moved.
234	 */
235	async function disableRegistrarAutorenew(domain: string): Promise<void> {
236	  try {
237	    await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:disableAutorenew`);
238	  } catch (e) {
239	    console.error(`[registrar] failed to disable name.com's own auto-renew for ${domain} — it may renew/charge independently of our sweep`, e);
240	  }
241	}
242	
243	/** Registers for `years` at the given expected price (from checkDomains). */
244	export async function registerDomain(
245	  domain: string,
246	  years: number,
247	  contact: RegistrantContact,
248	  purchaseCents: number
249	): Promise<{ expiresAt?: Date }> {
250	  const c = ncContact(contact);
251	  const json = await nc("POST", "/v4/domains", {
252	    domain: {
253	      domainName: domain,
254	      contacts: { registrant: c, admin: c, tech: c, billing: c },
255	      privacyEnabled: true,
256	    },
257	    purchasePrice: purchaseCents / 100,
258	    years,
259	  });
260	  await disableRegistrarAutorenew(domain);
261	  const exp = json?.domain?.expireDate ?? json?.order?.expireDate;
262	  return { expiresAt: exp ? new Date(exp) : undefined };
263	}
264	
265	export async function renewDomain(domain: string, years: number, purchaseCents: number): Promise<void> {
266	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:renew`, {
267	    purchasePrice: purchaseCents / 100,
268	    years,
269	  });
270	  await disableRegistrarAutorenew(domain);
271	}
272	
273	export async function domainInfo(domain: string): Promise<{ expires?: Date; created?: Date }> {
274	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}`);
275	  return {
276	    expires: json?.expireDate ? new Date(json.expireDate) : undefined,
277	    created: json?.createDate ? new Date(json.createDate) : undefined,
278	  };
279	}
