281	// ---------- Nameservers / registrar lock / outbound-transfer auth code ----------
282	//
283	// Consolidated out of lib/actions-domains-advanced.ts and
284	// lib/actions-domains-dns.ts, which each had their own private name.com
285	// client hitting these same endpoints. `lockDomain`/`unlockDomain` are
286	// shared by both files: advanced.ts's outbound-transfer flow only ever
287	// unlocks, dns.ts's registrar-lock toggle does both.
288	
289	export async function setNameservers(domain: string, nameservers: string[]): Promise<void> {
290	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:setNameservers`, { nameservers });
291	}
292	
293	export async function lockDomain(domain: string): Promise<void> {
294	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:lock`, {});
295	}
296	
297	export async function unlockDomain(domain: string): Promise<void> {
298	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:unlock`, {});
299	}
300	
301	/** Current registrar-lock state, read straight off the domain resource. */
302	export async function isDomainLocked(domain: string): Promise<boolean> {
303	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}`);
304	  return json?.locked === true;
305	}
306	
307	/** EPP/auth code for an outbound transfer. Null when the registrar has none to give. */
308	export async function getAuthCode(domain: string): Promise<string | null> {
309	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}:getAuthCode`);
310	  return json?.authCode ? String(json.authCode) : null;
311	}
312	
313	// ---------- Inbound transfers (transfer-in) ----------
314	//
315	// name.com v4 transfers:
316	//   POST /v4/transfers                      { domainName, authCode, privacyEnabled, purchasePrice }
317	//   GET  /v4/transfers                      -> { transfers: [...] }
318	//   GET  /v4/transfers/{domainName}         -> { domainName, email, status }
319	//   POST /v4/transfers/{domainName}:cancel  -> { domainName, email, status }
320	//
321	// A transfer always includes a 1-year extension of the registration, which is
322	// why it is priced off the TLD's RENEWAL rate rather than its promo/first-year
323	// registration rate.
324	
325	/** Compressed sandbox timeline (real transfers take 5-7 days — see SANDBOX_* notes). */
326	const SANDBOX_APPROVAL_MS = 2 * 60_000;
327	const SANDBOX_REGISTRY_MS = 5 * 60_000;
328	
329	/** Deterministic synthetic per-year cost for a TLD in sandbox (integer cents). */
330	function sandboxTldCostCents(domain: string): number {
331	  const tld = domain.slice(domain.lastIndexOf(".") + 1);
332	  let h = 0;
333	  for (const ch of tld) h = (h * 31 + ch.charCodeAt(0)) % 997;
334	  return 900 + (h % 21) * 50; // $9.00 – $19.00
335	}
336	
337	export type TransferCheck = {
338	  domain: string;
339	  /** True when we believe an inbound transfer can be submitted for this name. */
340	  transferable: boolean;
341	  /** Plain-English reason when `transferable` is false. */
342	  reason: string | null;
343	  premium: boolean;
344	  /** RETAIL price the customer pays — covers the transfer + 1 extra year. */
345	  priceCents: number | null;
346	  /** Registrar cost we pay name.com (what we send as `purchasePrice`). */
347	  costCents: number | null;
348	};
349	
350	/**
351	 * The registrar cost of transferring `domain`, in integer cents.
352	 *
353	 * Transfers are billed at the TLD's renewal rate. name.com only reliably prices
354	 * a name it can see, so we try three sources in order and give up honestly:
355	 *   1. the availability result for the domain itself,
356	 *   2. the per-domain pricing endpoint,
357	 *   3. a throwaway probe name on the same TLD — TLD pricing is per-TLD, so an
358	 *      unregistered sibling quotes the same renewal rate.
359	 */
360	async function transferCostCents(domain: string, availability: any): Promise<number | null> {
361	  const own = dollarsToCents(availability?.renewalPrice ?? availability?.purchasePrice);
362	  if (own !== null && own > 0) return own;
363	
364	  try {
365	    const p = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}:getPricing`);
366	    const quoted = dollarsToCents(p?.transferPrice ?? p?.renewalPrice ?? p?.purchasePrice);
367	    if (quoted !== null && quoted > 0) return quoted;
368	  } catch {
369	    /* endpoint unavailable for this TLD/account — fall through to the probe */
370	  }
371	
372	  const tld = domain.slice(domain.indexOf(".") + 1);
373	  try {
374	    const probe = `nxeon-price-probe-${Math.random().toString(36).slice(2, 10)}.${tld}`;
375	    const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [probe] });
376	    const r = (json.results ?? [])[0];
377	    const c = dollarsToCents(r?.renewalPrice ?? r?.purchasePrice);
378	    if (c !== null && c > 0) return c;
379	  } catch {
380	    /* registrar unhappy — no price, caller surfaces that plainly */
381	  }
382	  return null;
383	}
