470	export type TransferInfo = {
471	  domain: string;
472	  /** Raw registrar status, shown to the customer verbatim. */
473	  status: string;
474	  /** Where the losing registrar sent the approval email (not every TLD sends one). */
475	  email: string | null;
476	};
