478	/**
479	 * Submit an inbound transfer. `purchaseCents` is the registrar COST (integer
480	 * cents) — the same "what we expect to pay" contract `registerDomain` uses.
481	 * The auth code is passed straight through and never logged.
482	 */
483	export async function createTransfer(
484	  domain: string,
485	  authCode: string,
486	  purchaseCents: number
487	): Promise<TransferInfo> {
488	  if (SANDBOX) {
489	    // Names containing "fail" reject at submit time so staging can exercise the
490	    // "registrar refused, customer not charged" path.
491	    if (domain.includes("fail")) throw new RegistrarError("namecom", "transfer rejected by the registry (sandbox)");
492	    return { domain, status: "pendingOwnerApproval", email: `owner@${domain}` };
493	  }
494	  const json = await nc("POST", "/v4/transfers", {
495	    domainName: domain,
496	    authCode,
497	    privacyEnabled: true,
498	    purchasePrice: purchaseCents / 100,
499	  });
500	  const t = json?.transfer ?? json ?? {};
501	  return {
502	    domain: t.domainName ?? domain,
503	    status: String(t.status ?? "pending"),
504	    email: t.email ? String(t.email) : null,
505	  };
506	}
507	
508	/**
509	 * Current state of an inbound transfer. Returns null when the registrar has no
510	 * transfer for this domain — which is a NORMAL answer once a transfer settles
511	 * and drops off the list, so callers must resolve that against `domainInfo`
512	 * rather than treating it as a failure.
513	 *
514	 * `startedAt` is only read in SANDBOX, where it drives a synthetic progression
515	 * (registrar.ts holds no state of its own).
516	 */
517	export async function getTransfer(domain: string, startedAt?: Date | null): Promise<TransferInfo | null> {
518	  if (SANDBOX) {
519	    const age = Date.now() - (startedAt?.getTime() ?? Date.now());
520	    const status =
521	      age < SANDBOX_APPROVAL_MS
522	        ? "pendingOwnerApproval"
523	        : age < SANDBOX_REGISTRY_MS
524	          ? "pendingRegistry"
525	          : "completed";
526	    return { domain, status, email: `owner@${domain}` };
527	  }
528	  const t = await nc("GET", `/v4/transfers/${encodeURIComponent(domain)}`, undefined, { nullOn404: true });
529	  if (!t) return null;
530	  return {
531	    domain: t.domainName ?? domain,
532	    status: String(t.status ?? "pending"),
533	    email: t.email ? String(t.email) : null,
534	  };
535	}
536	
537	/**
538	 * Ask the registrar to cancel an in-flight inbound transfer. Throws if the
539	 * registrar refuses (e.g. the transfer already completed at the registry) —
540	 * callers must NOT credit the customer unless this resolves.
541	 */
542	export async function cancelTransfer(domain: string): Promise<TransferInfo> {
543	  if (SANDBOX) return { domain, status: "cancelled", email: null };
544	  const t = await nc("POST", `/v4/transfers/${encodeURIComponent(domain)}:cancel`, {});
545	  return {
546	    domain: t?.domainName ?? domain,
547	    status: String(t?.status ?? "cancelled"),
548	    email: t?.email ? String(t.email) : null,
549	  };
550	}
551	
552	/** All inbound transfers on the reseller account (ops/debug — not used per-domain). */
553	export async function listTransfers(): Promise<TransferInfo[]> {
554	  if (SANDBOX) return [];
555	  const json = await nc("GET", "/v4/transfers");
556	  return (json.transfers ?? []).map((t: any) => ({
557	    domain: t.domainName,
558	    status: String(t.status ?? "pending"),
559	    email: t.email ? String(t.email) : null,
560	  }));
561	}
