1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { readFileSync, readdirSync, statSync } from "node:fs";
4	import { join, extname } from "node:path";
5	import { stripComments } from "./_source-tools.ts";
6	
7	/**
8	 * A signed-in customer must never learn which registrar Nxeon uses behind the
9	 * scenes — search results, error messages, DNS/nameserver copy, and the AI
10	 * chat assistant all have to stay registrar-agnostic (see the multi-registrar
11	 * plan's leak list). This is a standing tripwire, not a one-time fix: it scans
12	 * every customer-facing surface for the literal registrar names and fails the
13	 * moment one shows up again, whether from a careless copy change or a future
14	 * registrar integration (Namecheap, eNom, ...).
15	 *
16	 * `app/admin/**` is excluded on purpose — the admin console is the ONE place
17	 * this information is allowed, and is expected, to appear (e.g. a per-domain
18	 * "Registrar" column).
19	 *
20	 * Comments are stripped before matching (via `stripComments`, same helper the
21	 * other structural tripwires use) so an internal doc comment explaining "this
22	 * calls name.com's API" doesn't fail the test — only text a customer could
23	 * actually see (JSX, string literals, template literals) counts.
24	 */
25	
26	const ROOT = join(import.meta.dirname, "..");
27	const SCAN_DIRS = ["components/customer", "app/dashboard"];
28	const EXTENSIONS = new Set([".ts", ".tsx"]);
29	
30	// Word-boundary on "enom" so it doesn't fire on ordinary English words that
31	// happen to contain that substring (e.g. "denominator", "phenomenon"). A
32	// negative lookbehind on "name.com" so a placeholder example domain like
33	// "another-name.com" (a stand-in for "put your own domain here", unrelated to
34	// the registrar) doesn't fire either — only "name.com" as its own token does.
35	const FORBIDDEN: { label: string; pattern: RegExp }[] = [
36	  { label: "name.com", pattern: /(?<![a-z0-9-])name\.com/i },
37	  { label: "Namecheap", pattern: /namecheap/i },
38	  { label: "eNom", pattern: /\benom\b/i },
39	];
40	
41	/**
42	 * A second, narrower category: phrasing that names no vendor but still tells a
43	 * customer "a third-party company handles Nxeon's own domain registration" —
44	 * e.g. "activates once the registrar integration is configured", "applied at
45	 * the registrar", "checking with the registrar". Nxeon's brand voice is
46	 * first-person-owner ("we ARE the provider"), so even a vendor-agnostic
47	 * implication of an external registrar behind NXEON'S OWN registrations is a
48	 * leak, not just a named one — this was found and fixed across 13 sites after
49	 * the FORBIDDEN literal-name sweep above already passed clean.
50	 *
51	 * Scoped narrowly to phrases that only ever appear when describing Nxeon's OWN
52	 * backend (never "your other/current/new registrar" during an inbound
53	 * transfer, which is a real external entity and legitimate to name). Two
54	 * files are excluded entirely because EVERY "registrar" mention in them refers
55	 * to the customer's own OTHER registrar during a transfer-in — a real company
56	 * Nxeon doesn't control, correctly described.
57	 */
58	const IMPLIED_THIRD_PARTY_EXCLUDE = new Set([
59	  "components/customer/DomainTransferIn.tsx",
60	  "components/customer/DomainTransferInWizard.tsx",
61	]);
62	const IMPLIED_THIRD_PARTY: { label: string; pattern: RegExp }[] = [
63	  { label: "the registrar integration", pattern: /the registrar integration/i },
64	  { label: "at the registrar", pattern: /\bat the registrar\b/i },
65	  { label: "with the registrar", pattern: /\bwith the registrar\b/i },
66	  { label: "from the registrar", pattern: /\bfrom the registrar\b/i },
67	  { label: "registrar API", pattern: /\bregistrar api\b/i },
68	  { label: "registrar lock", pattern: /\bregistrar lock\b/i },
69	  { label: "registrar record", pattern: /\bregistrar record\b/i },
70	];
71	
72	function walk(dir: string, out: string[] = []): string[] {
73	  for (const entry of readdirSync(dir)) {
74	    const full = join(dir, entry);
75	    const st = statSync(full);
76	    if (st.isDirectory()) walk(full, out);
77	    else if (EXTENSIONS.has(extname(entry))) out.push(full);
78	  }
79	  return out;
80	}
81	
82	test("no registrar identity leaks into customer-facing dashboard/components code", () => {
83	  const offenders: string[] = [];
84	  for (const dir of SCAN_DIRS) {
85	    for (const file of walk(join(ROOT, dir))) {
86	      const src = stripComments(readFileSync(file, "utf8"));
87	      const rel = file.slice(ROOT.length + 1);
88	      for (const { label, pattern } of FORBIDDEN) {
89	        if (pattern.test(src)) offenders.push(`${rel} — matched "${label}"`);
90	      }
91	      if (!IMPLIED_THIRD_PARTY_EXCLUDE.has(rel)) {
92	        for (const { label, pattern } of IMPLIED_THIRD_PARTY) {
93	          if (pattern.test(src)) offenders.push(`${rel} — matched "${label}"`);
94	        }
95	      }
96	    }
97	  }
98	  assert.deepEqual(
99	    offenders,
100	    [],
101	    `Registrar identity must never be visible to a signed-in customer, but found:\n${offenders.join("\n")}`
102	  );
103	});
