59	function beginSubmit(key: string): boolean {
60	  const now = Date.now();
61	  const heldUntil = inFlightSubmits.get(key);
62	  if (heldUntil !== undefined && heldUntil > now) return false;
63	  if (inFlightSubmits.size > 2000) {
64	    for (const [k, v] of inFlightSubmits) if (v <= now) inFlightSubmits.delete(k);
65	  }
66	  inFlightSubmits.set(key, now + SUBMIT_GUARD_MS);
67	  return true;
68	}
