151	    mailboxLocalPart: string | null;
152	    partnerSource: string | null;
153	  },
154	  priced: DomainOrderPrice,
155	): Promise<DomainRegistrationResult> {
156	  const { domain, contact, mailboxLocalPart, partnerSource } = params;
157	  const dTerm = domainTerm(params.years);
158	  const totalCents = domainTermPriceCents(priced.priceCents, dTerm.years);
159	  const registrarCostCents = priced.costCents * dTerm.years;
160	
161	  const existing = await db.domain.findUnique({ where: { name: domain } });
162	  if (existing) {
163	    if (existing.userId !== user.id) throw new DomainOrderError("This domain is already managed by another account.");
164	    if (existing.status === "PENDING") {
165	      throw new DomainOrderError("You already have a registration in progress for this domain.");
166	    }
167	    // FAILED = a previous attempt never actually registered anything and was
168	    // already refunded — see purchaseDomain's identical carve-out above for
169	    // why this must not permanently block a retry. Every other status still
170	    // does (ACTIVE/EXPIRED/TRANSFER_* all mean something real exists here).
171	    if (existing.status !== "FAILED") {
172	      throw new DomainOrderError(`You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).`);
173	    }
174	  }
175	
176	  if (user.balanceCents < totalCents) {
177	    throw new DomainOrderError(`Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.`);
178	  }
179	
180	  let record;
181	  try {
182	    record = await db.$transaction(async (tx) => {
183	      // Re-check inside the transaction: the availability round-trip above is
184	      // slow enough for a second submit to slip in. `Domain.name` is UNIQUE, so
185	      // even if this read misses, the create below rolls the whole debit back.
186	      const dupe = await tx.domain.findUnique({ where: { name: domain } });
187	      if (dupe) {
188	        if (dupe.userId !== user.id || dupe.status !== "FAILED") throw new DuplicateDomainError();
189	        // Clear the stale FAILED row so the create below doesn't collide with
190	        // the UNIQUE constraint on `name` — safe: it belongs to this same
191	        // user and holds no real registration (confirmed just above too;
192	        // this is the transaction-safe re-check for the retry race).
193	        await tx.domain.delete({ where: { id: dupe.id } });
194	      }
195	      await debitWallet(tx, user.id, totalCents);
196	      await tx.walletTransaction.create({
197	        data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
198	      });
199	      return tx.domain.create({
200	        data: {
201	          name: domain,
202	          userId: user.id,
203	          priceCents: priced.priceCents,
204	          costCents: priced.costCents,
205	          termYears: dTerm.years,
206	          status: "PENDING",
207	          registrar: "name.com",
208	          partnerSource: partnerSource ?? null,
209	        },
210	      });
211	    });
212	  } catch (e) {
213	    if (e instanceof InsufficientBalanceError) throw new DomainOrderError("Insufficient balance — top up your wallet first.");
214	    if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
215	      throw new DomainOrderError("This domain is already being registered — you have not been charged twice.");
216	    }
217	    throw e;
218	  }
219	
220	  try {
221	    const { expiresAt } = await registerDomain(domain, dTerm.years, contact, registrarCostCents);
222	    const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
223	    await db.domain.update({
224	      where: { id: record.id },
225	      data: {
226	        status: "ACTIVE",
227	        registeredAt: new Date(),
228	        expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
229	      },
230	    });
231	    await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
232	    await db.notification.create({
233	      data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
234	    });
235	    // Tell the partner (best-effort, never blocks the order) — only for orders
236	    // tagged via a partner deep link. Most domain registrations are direct Nxeon
237	    // customers and must never be forwarded to a partner's webhook.
238	    if (partnerSource === "kodely") {
239	      await notifyPartner("domain.registered", { userId: user.id, domain, expiresAt: info.expires ?? null });
240	    }
241	    // Every domain registered through Nxeon includes a free inbox — see
242	    // lib/domain-inbox-email.ts. Best-effort: never lets a mailbox hiccup
243	    // undo a domain purchase that already succeeded.
244	    await setupDomainInboxEmail({
245	      userId: user.id,
246	      domainName: domain,
247	      expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
248	      mailboxLocalPart,
249	    });
250	    return { kind: "active", domainId: record.id };
251	  } catch (e: any) {
252	    // `reason` is RAW (kept for the audit trail below — admin-only). Anything
253	    // that ends up on `Domain.error` or in a returned `message`, on the other
254	    // hand, reaches the customer directly (the FAILED banner on the domain
255	    // page, and lib/kb-tools.ts's AI chat context) — those use `customerReason`
256	    // instead, which is registrar-name-free by construction when `e` is a
257	    // `RegistrarError`.
258	    const reason = String(e?.message ?? e).slice(0, 400);
259	    const customerReason = errMsg(e);
260	    // NEVER refund blind: a timeout/5xx often means the order DID go through.
261	    const verdict = await verifyRegistration(domain);
262	
263	    if (verdict.state === "registered") {
264	      // The registration exists — keep the charge and finish the record.
265	      await db.domain.update({
266	        where: { id: record.id },
267	        data: {
268	          status: "ACTIVE",
269	          registeredAt: new Date(),
270	          expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
271	          error: `Recovered after a registration issue: ${customerReason}`.slice(0, 500),
272	        },
273	      });
274	      await db.auditLog.create({
275	        data: { userId: user.id, action: "domain.register.recovered", detail: `${domain}: ${reason}`.slice(0, 500) },
276	      });
277	      await db.notification.create({
278	        data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
279	      });
280	      // Recovered-but-registered still counts as a successful registration —
281	      // it gets the same free inbox the happy path does.
282	      await setupDomainInboxEmail({
283	        userId: user.id,
284	        domainName: domain,
285	        expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
286	        mailboxLocalPart,
287	      });
288	      return { kind: "active", domainId: record.id };
289	    }
290	
291	    if (verdict.state === "not-registered") {
292	      // Confirmed still available at the registrar — refunding is safe.
293	      await db.$transaction([
294	        db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
295	        db.walletTransaction.create({
296	          data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
297	        }),
298	        db.domain.update({
299	          where: { id: record.id },
300	          data: { status: "FAILED", error: customerReason.slice(0, 500) },
301	        }),
302	      ]);
303	      // The raw (possibly registrar-attributed) reason goes here, not on
304	      // Domain.error — matching the "recovered"/"needs_review" branches above,
305	      // which log it the same way. Without this, the only place the real
306	      // diagnostic ever lands is an ephemeral server console line
307	      // (registrarSafeMessage's own console.error), which is far less
308	      // discoverable for ops later than a normal audit-log entry.
309	      await db.auditLog.create({
310	        data: { userId: user.id, action: "domain.register.failed", detail: `${domain}: ${reason}`.slice(0, 500) },
311	      });
312	      return {
313	        kind: "refunded",
314	        domainId: record.id,
315	        message: `Registration failed: ${customerReason.slice(0, 200)} (you were refunded).`,
316	      };
317	    }
318	
319	    // Unknown: leave PENDING and charged, flag for manual review. Refunding
320	    // here risks giving away a domain we actually paid the registrar for.
321	    await db.domain.update({
322	      where: { id: record.id },
323	      data: { status: "PENDING", error: `NEEDS REVIEW — registration status unconfirmed: ${customerReason}`.slice(0, 500) },
324	    });
325	    await db.auditLog.create({
326	      data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
327	    });
328	    await db.notification.create({
329	      data: {
330	        userId: user.id,
331	        title: `Domain ${domain} needs review`,
332	        body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
333	        href: `/dashboard/domains/${record.id}`,
334	      },
335	    });
336	    return {
337	      kind: "needs-review",
338	      domainId: record.id,
339	      message:
340	        `We could not confirm ${domain} (${customerReason.slice(0, 120)}). ` +
341	        `It is marked for review — do not retry, you will not be charged twice.`,
342	    };
343	  }
344	}
