346	export async function purchaseDomain(
347	  prev: any,
348	  formData: FormData,
349	): Promise<{ error?: string; checkout?: { clientSecret: string; publishableKey: string } }> {
350	  // Spend path: registering a domain debits the wallet AND buys a non-refundable
351	  // asset from a registrar in the customer's name, with registrant contact details
352	  // taken from this form. `submitTransferIn` — the same product, the same money —
353	  // has carried this guard since it was written; registration and renewal never did.
354	  await assertNotImpersonating();
355	  const user = await requireUser();
356	  // Purchase gate: an unverified address means we cannot reach the person we
357	  // are about to charge. See lib/email-verification.ts.
358	  const unverified = await emailVerificationError(user);
359	  if (unverified) return { error: unverified };
360	  // Feature flag: domain registration can be switched off platform-wide.
361	  if (!(await getSettingBool("feature_domains", true))) {
362	    return { error: "Domain registration is currently unavailable." };
363	  }
364	  if (!registrarConfigured()) {
365	    return { error: "Domain registration is not configured yet." };
366	  }
367	  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
368	  // /dashboard/domains, captured into a cookie by PartnerSourceCapture). Read
369	  // synchronously here (unlike the VPS path, domain purchase is a same-request
370	  // wallet debit — no Stripe checkout/webhook race to round-trip through).
371	  const partnerSource = partnerSourceFromCookie(await cookies());
372	  const contactSchema = z.object({
373	    firstName: z.string().min(1).max(60),
374	    lastName: z.string().min(1).max(60),
375	    address1: z.string().min(1).max(120),
376	    city: z.string().min(1).max(60),
377	    stateProvince: z.string().min(1).max(60),
378	    postalCode: z.string().min(1).max(20),
379	    country: z.string().length(2),
380	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
381	    email: z.string().email(),
382	  });
383	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
384	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
385	  const dTerm = domainTerm(Number(formData.get("years") ?? 1));
386	  // Free Domain Inbox — the mailbox local-part the customer optionally chose
387	  // during registration (components/customer/DomainRegisterWizard.tsx's Email
388	  // step). Empty is valid: the inbox is still reserved, just mailbox-less
389	  // until they add one from /dashboard/email. See lib/domain-inbox-email.ts.
390	  const mailboxLocalPart = String(formData.get("mailboxLocalPart") ?? "").trim().toLowerCase() || null;
391	
392	  const contactParsed = contactSchema.safeParse({
393	    firstName: formData.get("firstName"),
394	    lastName: formData.get("lastName"),
395	    address1: formData.get("address1"),
396	    city: formData.get("city"),
397	    stateProvince: formData.get("stateProvince"),
398	    postalCode: formData.get("postalCode"),
399	    country: String(formData.get("country") ?? "").toUpperCase(),
400	    phone: formData.get("phone"),
401	    email: formData.get("email"),
402	  });
403	  if (!contactParsed.success) {
404	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
405	  }
406	  const contact = contactParsed.data as RegistrantContact;
407	
408	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
409	  // Also covers the card-shortfall branch below: that call only OPENS a Stripe
410	  // session (it doesn't touch the wallet or the registrar yet), so holding the
411	  // same guard just stops a double-click from opening two sessions for once
412	  // domain — it never blocks the SEPARATE call that later fulfils the paid one.
413	  const guardKey = `register:${user.id}:${domain}`;
414	  if (!beginSubmit(guardKey)) {
415	    return { error: "That registration is already being processed — give it a moment before retrying." };
416	  }
417	
418	  try {
419	    const existing = await db.domain.findUnique({ where: { name: domain } });
420	    if (existing) {
421	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
422	      if (existing.status === "PENDING") {
423	        return { error: "You already have a registration in progress for this domain." };
424	      }
425	      // FAILED means the earlier attempt never actually registered anything
426	      // and was already refunded (see the FAILED branch below/in
427	      // registerDomainCore) — nothing is owned under this name, so blocking a
428	      // retry here would contradict the platform's own promise ("you're never
429	      // charged for a name you don't get"). Real bug found live: a customer
430	      // hit a one-time registrar failure and then could never try that exact
431	      // domain again. Every other terminal status still blocks.
432	      if (existing.status !== "FAILED") {
433	        return { error: `You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).` };
434	      }
435	    }
436	
437	    // Live availability + retail(markup) & cost prices from name.com
438	    let priceCents: number; // retail per year (customer)
439	    let costCents: number; // registrar cost per year (us)
440	    try {
441	      const [check] = await checkDomains([domain]);
442	      if (!check) return { error: "Could not check availability. Try again." };
443	      if (!check.available) return { error: "Domain is not available." };
444	      if (check.premium) return { error: "Premium domains are not supported yet." };
445	      if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
446	      priceCents = check.priceCents;
447	      costCents = check.costCents;
448	    } catch (e: any) {
449	      return { error: errMsg(e) };
450	    }
451	
452	    const totalCents = domainTermPriceCents(priceCents, dTerm.years);
453	    // Whether the customer opted to apply wallet balance at all (the wizard's
454	    // Review-step toggle, same one DeployWizard.tsx has always had) — real gap
455	    // found live: this was hardcoded `true` with no way for a customer to
456	    // choose card instead when the wallet already covered the total.
457	    const useWallet = formData.get("useWallet") !== "0";
458	    // Same split math every other card-funded purchase on this platform uses
459	    // (lib/wallet-split.ts) — NOT a bare `totalCents - balanceCents`. That naive
460	    // subtraction can land a 1–49c remainder on the card, which Stripe rejects
461	    // outright; `walletSplit` either clamps the card leg up to its 50c floor
462	    // (taking a touch less wallet) or, if the WHOLE total is under the floor,
463	    // drops the card leg entirely so the wallet is the only leg (surfaced below
464	    // by `cardCents <= 0` falling through to the direct-wallet path, which does
465	    // its own honest "Insufficient balance" check rather than a raw Stripe error).
466	    const { cardCents } = walletSplit({ dueCents: totalCents, balanceCents: user.balanceCents, useWallet });
467	
468	    if (cardCents > 0) {
469	      // Wallet doesn't cover it — open the embedded Payment step for the
470	      // SHORTFALL, mirroring payAndDeploy's wallet+card split (lib/actions.ts).
471	      // Nothing is charged or registered here; the actual registration only
472	      // happens once the card clears, via placeDomainCardOrder below.
473	      if (!stripeConfigured()) {
474	        return {
475	          error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}, and card payments aren't set up on this platform yet. Top up your wallet to continue.`,
476	        };
477	      }
478	      const priced: DomainOrderPrice = { priceCents, costCents };
479	      // Stash the registrant contact + frozen price BEFORE opening the session —
480	      // see DomainOrderIntent's doc comment in schema.prisma for why this can't
481	      // just ride in Stripe metadata like a VPS/hosting/email order's intent
482	      // does (a registrant contact has no combined length cap that fits
483	      // Stripe's 500-char-per-value limit).
484	      const stashed = await db.domainOrderIntent.create({
485	        data: {
486	          userId: user.id,
487	          domain,
488	          years: dTerm.years,
489	          firstName: contact.firstName,
490	          lastName: contact.lastName,
491	          address1: contact.address1,
492	          city: contact.city,
493	          stateProvince: contact.stateProvince,
494	          postalCode: contact.postalCode,
495	          country: contact.country,
496	          phone: contact.phone,
497	          email: contact.email,
498	          mailboxLocalPart,
499	          partnerSource: partnerSource ?? null,
500	          priceCents,
501	          costCents,
502	        },
503	      });
504	      let checkout;
505	      try {
506	        checkout = await createDomainOrderPaymentSession(user, cardCents, domain, dTerm.years, stashed.id, priced);
507	      } catch (e: any) {
508	        return { error: String(e?.message ?? e).slice(0, 200) };
509	      }
510	      if (!checkout) {
511	        return { error: "Card payments aren't available right now. Top up your wallet to continue." };
512	      }
513	      return { checkout };
514	    }
515	
516	    // Wallet covers it — register immediately, exactly as this always has.
517	    let result: DomainRegistrationResult;
518	    try {
519	      result = await registerDomainCore(
520	        user,
521	        { domain, years: dTerm.years, contact, mailboxLocalPart, partnerSource: partnerSource ?? null },
522	        { priceCents, costCents },
523	      );
524	    } catch (e) {
525	      if (e instanceof DomainOrderError) return { error: e.message };
526	      throw e;
527	    }
528	    if (result.kind !== "active") return { error: result.message };
529	    // `?new=1` triggers the one-time "domain registered" success banner +
530	    // hosting/VPS upsell on the domain page (app/dashboard/domains/[id]/page.tsx).
531	    redirect(`/dashboard/domains/${result.domainId}?new=1`);
532	  } finally {
533	    endSubmit(guardKey);
534	  }
535	}
