538	 * Fulfil a domain registration paid by card — called only from
539	 * lib/fulfil-checkout.ts after the card leg is confirmed paid, exactly like
540	 * `placeHostingCardOrder`/`placeEmailCardOrder` (lib/actions-hosting.ts /
541	 * lib/actions-email-hosting.ts). Re-verifies EVERYTHING from the Stripe
542	 * session id alone — this file has `"use server"`, so this export is a
543	 * client-invokable Server Action, and it must trust nothing a caller supplies
544	 * except a session id that only Stripe itself could have produced as paid.
545	 *
546	 * The DomainOrderIntent row (not `purpose.sold`) is the authoritative source
547	 * for both the registrant contact and the frozen price — see that model's doc
548	 * comment in schema.prisma.
549	 */
550	export async function placeDomainCardOrder(
551	  sessionId: string,
552	): Promise<
553	  | { skip: true }
554	  | { error: string }
555	  | { domainId: string; kind: "active" }
556	  | { domainId: string; kind: "refunded" | "needs-review"; message: string }
557	> {
558	  const purpose = await getCheckoutPurpose(sessionId);
559	  if (purpose.kind !== "domainOrder") return { skip: true };
560	
561	  const [user, stashed] = await Promise.all([
562	    db.user.findUnique({ where: { id: purpose.userId } }),
563	    db.domainOrderIntent.findUnique({ where: { id: purpose.domainOrderId } }),
564	  ]);
565	  if (!user) return { error: "user not found for paid domain order" };
566	  if (!stashed) return { error: "domain order intent not found — it may already have been fulfilled and cleared" };
567	  // The row was written by THIS user's own purchaseDomain call, moments before
568	  // the session it is referenced from — a mismatch means the session's
569	  // metadata and the row it points at disagree about whose order this is,
570	  // which must never be trusted silently.
571	  if (stashed.userId !== purpose.userId) {
572	    return { error: `domain order intent ${stashed.id} belongs to a different user than the paid session` };
573	  }
574	
575	  const contact: RegistrantContact = {
576	    firstName: stashed.firstName,
577	    lastName: stashed.lastName,
578	    address1: stashed.address1,
579	    city: stashed.city,
580	    stateProvince: stashed.stateProvince,
581	    postalCode: stashed.postalCode,
582	    country: stashed.country,
583	    phone: stashed.phone,
584	    email: stashed.email,
585	  };
586	
587	  let result: DomainRegistrationResult;
588	  try {
589	    result = await registerDomainCore(
590	      user,
591	      {
592	        domain: stashed.domain,
593	        years: stashed.years,
594	        contact,
595	        mailboxLocalPart: stashed.mailboxLocalPart,
596	        partnerSource: stashed.partnerSource,
597	      },
598	      { priceCents: stashed.priceCents, costCents: stashed.costCents },
599	    );
600	  } catch (e) {
601	    if (e instanceof DomainOrderError) return { error: e.message };
602	    throw e;
603	  }
604	
605	  if (result.kind === "active") return { domainId: result.domainId, kind: "active" };
606	  return { domainId: result.domainId, kind: result.kind, message: result.message };
607	}
