612	export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
613	  // Spend path: a manual renewal debits the wallet and spends at the registrar.
614	  // See purchaseDomain above.
615	  await assertNotImpersonating();
616	  const user = await requireUser();
617	  // Purchase gate: a MANUAL renewal is a fresh spend decision. Automatic domain
618	  // renewal runs in the worker and does not come through here, so no existing
619	  // domain can lapse because of this check.
620	  const unverifiedRenew = await emailVerificationError(user);
621	  if (unverifiedRenew) return { error: unverifiedRenew };
622	  const domain = await db.domain.findUnique({ where: { id: domainId } });
623	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
624	  if (domain.status === "PENDING") return { error: "This domain's registration is still being confirmed." };
625	  if (domain.status === "FAILED") return { error: "This domain is not registered." };
626	
627	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
628	  const guardKey = `renew:${domain.userId}:${domain.name}`;
629	  if (!beginSubmit(guardKey)) {
630	    return { error: "A renewal for this domain is already in progress." };
631	  }
632	
633	  try {
634	    const dTerm = domainTerm(domain.termYears);
635	    const renewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
636	    const owner = await db.user.findUnique({ where: { id: domain.userId } });
637	    if (!owner || owner.balanceCents < renewCents) return { error: "Insufficient balance." };
638	
639	    const dbExpiry = domain.expiresAt ?? null;
640	
641	    // Idempotency: charge and expiry advance together in one transaction below,
642	    // so if the registrar expiry is already ahead of ours a previous attempt
643	    // renewed but never got charged/recorded. Adopt that renewal instead of
644	    // buying a second year.
645	    let registrarExpiry: Date | undefined;
646	    try {
647	      registrarExpiry = (await domainInfo(domain.name)).expires;
648	    } catch {
649	      /* non-fatal: fall through to a normal renew */
650	    }
651	    const alreadyRenewed =
652	      !!registrarExpiry && !!dbExpiry && registrarExpiry.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS;
653	
654	    if (!alreadyRenewed) {
