656	        await renewDomain(domain.name, dTerm.years, (domain.costCents || domain.priceCents) * dTerm.years);
657	      } catch (e: any) {
658	        // The registrar call is the FIRST thing that happens, before any debit,
659	        // so "you have not been charged" is a fact here, not a hope — and saying
660	        // it stops a customer retrying a renewal they think half-succeeded.
661	        return {
