818	/**
819	 * One-click: point apex + www at the platform's public IP.
820	 *
821	 * ADD BEFORE DELETE, per host. This used to delete every apex/www A record and
822	 * only then add the replacements — so a registrar hiccup, a rate limit or a
823	 * network blip in between took the domain DARK and left it that way, with an
824	 * error message that did not say the old records were already gone. That is the
825	 * "six domains dark while the run scored 4/4" failure shape: destructive work
826	 * done first, on the assumption the constructive half cannot fail.
827	 *
828	 * The new order is also idempotent — an A record already pointing at `ip` is
829	 * kept rather than churned — so clicking twice is free, and a half-finished run
830	 * can simply be retried.
831	 */
832	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
833	  let ctx;
834	  try {
835	    ctx = await ownedDomain(domainId);
836	  } catch (e: any) {
837	    return { error: e.message };
838	  }
839	  const ip = process.env.PUBLIC_IP;
840	  if (!ip) {
841	    return {
842	      error:
843	        "This platform doesn't have a public IP configured, so there is nothing to point the domain at. " +
844	        "Contact support — this is a platform configuration problem, not something you can fix from here.",
845	    };
846	  }
847	
848	  const done: string[] = [];
849	  try {
850	    const recs = await listRecords(ctx.domain.name);
851	    for (const host of ["", "www"]) {
852	      const label = host === "" ? ctx.domain.name : `www.${ctx.domain.name}`;
853	      const existing = recs.filter((r) => r.host === host && r.type === "A");
854	      const keep = existing.find((r) => r.answer === ip);
855	      // Constructive half FIRST: the name resolves somewhere at every instant.
856	      if (!keep) await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
857	      // Only now retire the records that point elsewhere.
858	      for (const r of existing) {
859	        if (keep && r.id === keep.id) continue;
860	        await deleteRecord(ctx.domain.name, r.id);
861	      }
862	      done.push(label);
863	    }
864	  } catch (e: any) {
865	    const reason = errMsg(e);
866	    return {
867	      error:
868	        `Part of this change was rejected (${reason}). ` +
869	        (done.length > 0
870	          ? `${done.join(" and ")} ${done.length === 1 ? "was" : "were"} pointed at ${ip} and ${done.length === 1 ? "is" : "are"} live; the rest was not changed. `
871	          : "Nothing was changed and your existing records are untouched. ") +
872	        `Wait a minute and click Point at server again — it is safe to repeat.`,
873	    };
874	  }
875	  revalidatePath(`/dashboard/domains/${domainId}`);
876	  return {};
877	}
