import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { registrarConfigured, checkDomains } from "@/lib/registrar";
import { db } from "@/lib/db";
import { EmptyState, fmtMoney } from "@/components/ui/primitives";
import { PortalHero } from "@/components/portal/PortalHero";
import { DomainRegisterWizard } from "@/components/customer/DomainRegisterWizard";
import type { DomainCheckResult } from "@/components/customer/DomainSearch";
import { IconMail } from "@/components/marketing/icons";
import { findDomainInboxPlan } from "@/lib/domain-inbox-email";
import { geoapifyConfigured } from "@/lib/geoapify";

export const dynamic = "force-dynamic";

const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;

export default async function RegisterDomainPage({
  searchParams,
}: {
  searchParams: Promise<{ domain?: string }>;
}) {
  const user = await requireUser();
  const { domain: raw } = await searchParams;
  const domain = (raw ?? "").toLowerCase().trim();
  const valid = DOMAIN_RE.test(domain);
  const configured = registrarConfigured();

  if (!configured) {
    return (
      <div className="space-y-6">
        <PortalHero variant="domains" title="Register domain" />
        <EmptyState
          title="Domain registration is not available yet"
          sub="Registration activates once this feature is configured. Your existing domains stay manageable in the meantime."
          action={
            <Link href="/dashboard/domains" className="btn-primary">
              Back to domains
            </Link>
          }
        />
      </div>
    );
  }

  // Live availability + price for the pre-selected domain (best-effort). Mapped
  // into the shared DomainCheckResult shape (status + sld/tld) the wizard uses.
  let initialCheck: DomainCheckResult | null = null;
  if (valid) {
    try {
      const [check] = await checkDomains([domain]);
      if (check) {
        const dot = check.domain.indexOf(".");
        const available = check.available && check.priceCents !== null;
        initialCheck = {
          domain: check.domain,
          sld: dot > 0 ? check.domain.slice(0, dot) : check.domain,
          tld: dot > 0 ? check.domain.slice(dot + 1) : "",
          status: available ? "available" : "taken",
          available,
          premium: check.premium,
          priceCents: available ? check.priceCents : null,
          renewCents: available ? check.renewCents : null,
        };
      }
    } catch {
      /* registrar briefly unreachable — the wizard can re-check client-side */
    }
  }

  // Real, live figures for the free-mailbox-with-hosting card below — sourced
  // from the same HostingPlan rows the /web-hosting pricing table reads, never
  // a guessed number. Shared Web Hosting bundles free mailboxes on every plan
  // (HostingPlan.mailboxes); Business Email bought on its own is never free
  // (see lib/actions-email-hosting.ts — firstMonthFreeAppliesTo("EMAIL") is
  // false), so the offer here is specifically "free mailbox WITH hosting."
  const hostingPlans = await db.hostingPlan.findMany({
    where: { active: true },
    select: { priceCents: true, mailboxes: true },
    orderBy: { priceCents: "asc" },
  });
  const hostingFromCents = hostingPlans.length ? hostingPlans[0].priceCents : null;
  const maxBundledMailboxes = hostingPlans.length
    ? Math.max(...hostingPlans.map((p) => p.mailboxes))
    : null;

  // The real, free "Domain Inbox" plan every Nxeon registration now includes
  // (lib/domain-inbox-email.ts). Null until prisma/seed-domain-inbox-plan.ts
  // has been run on this environment — the wizard's Email step is skipped
  // entirely rather than claiming a feature that isn't actually seeded yet.
  const inboxPlan = await findDomainInboxPlan();

  return (
    <div className="space-y-6">
      <PortalHero variant="domains" title="Register domain" sub="A few quick steps to secure your name.">
        <Link href="/dashboard/domains/ideas" className="btn-secondary">
          Need a name?
        </Link>
        <Link href="/dashboard/domains" className="btn-ghost">
          ← All domains
        </Link>
      </PortalHero>

      {hostingFromCents !== null && (
        <div className="card flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex items-start gap-4">
            <span className="flex h-11 w-11 flex-none items-center justify-center rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-brand-300">
              <IconMail size={22} />
            </span>
            <div>
              <h2 className="font-semibold text-white">Get a free mailbox with hosting</h2>
              <p className="mt-1 max-w-xl text-sm text-slate-400">
                Nxeon Web Hosting bundles{" "}
                {maxBundledMailboxes && maxBundledMailboxes > 1 ? `up to ${maxBundledMailboxes}` : "a"}{" "}
                professional you@yourdomain mailbox{maxBundledMailboxes === 1 ? "" : "es"} free with every
                plan — no separate email bill. Plans start at {fmtMoney(hostingFromCents)}/mo, and your
                first month is free.
              </p>
            </div>
          </div>
          <Link href="/web-hosting" className="btn-secondary shrink-0 self-start sm:self-center">
            See hosting plans
          </Link>
        </div>
      )}

      <DomainRegisterWizard
        initialDomain={valid ? domain : ""}
        initialCheck={initialCheck}
        defaultEmail={user.email}
        balanceCents={user.balanceCents}
        freeInboxPlan={inboxPlan ? { mailboxes: inboxPlan.mailboxes, storageGB: inboxPlan.storageGB } : null}
        geoapifyEnabled={geoapifyConfigured()}
      />
    </div>
  );
}
