/**
 * The registrar-agnostic contract every backend (name.com, Namecheap, ...)
 * implements. Modeled directly on `lib/registrar.ts`'s existing exports (the
 * Phase-1 consolidation of the 3 previously-duplicated name.com HTTP clients)
 * so `NameComRegistrar` (lib/registrars/index.ts) is a thin wrapper with zero
 * behavior change, and a second registrar can be added by matching this same
 * shape rather than inventing its own.
 *
 * `id` is the DB/dispatch value ("namecom" / "namecheap") — this is what a
 * `Domain.registrar` column or a `DomainOrderIntent.registrar` column would
 * store to remember which backend fulfilled an order (see the multi-registrar
 * plan's Phase 2/3). `label` is ADMIN-DISPLAY-ONLY ("name.com" / "Namecheap")
 * — per `test/registrar-leak-guard.test.ts`, it must never reach a
 * customer-facing function, string, or component. Every function below that
 * takes a domain/contact/etc. is otherwise identical in shape to
 * `lib/registrar.ts`'s exports so both registrars can be driven the same way.
 *
 * `transferOutcome`/`transferStatusLabel` (status bucketing) and
 * `domainMarkupPct`/`retailCents` (markup math) stay FREE, registrar-agnostic
 * functions in `lib/registrar.ts` — they are platform concepts, not
 * per-registrar behavior, so they are deliberately NOT part of this
 * interface. Callers use them exactly as they do today regardless of which
 * `RegistrarClient` produced the underlying status/price.
 */

export type DomainCheck = {
  domain: string;
  available: boolean;
  premium: boolean;
  priceCents: number | null; // RETAIL — what the customer pays (per year, first term)
  costCents: number | null; // registrar cost (per year, first term)
  renewCents: number | null; // RETAIL renewal price (per year, after the first term)
};

export type RegistrantContact = {
  firstName: string;
  lastName: string;
  address1: string;
  city: string;
  stateProvince: string;
  postalCode: string;
  country: string; // ISO-2
  phone: string; // +NN.NNNNNNNNNN
  email: string;
};

export type TransferCheck = {
  domain: string;
  /** True when we believe an inbound transfer can be submitted for this name. */
  transferable: boolean;
  /** Plain-English reason when `transferable` is false. */
  reason: string | null;
  premium: boolean;
  /** RETAIL price the customer pays — covers the transfer + 1 extra year. */
  priceCents: number | null;
  /** Registrar cost we pay, in integer cents (what we'd send as the purchase price). */
  costCents: number | null;
};

export type TransferInfo = {
  domain: string;
  /** Raw registrar status, shown to the customer verbatim. */
  status: string;
  /** Where the losing registrar sent the approval email (not every TLD sends one). */
  email: string | null;
};

export type DnsRecord = {
  id: number | string;
  host: string; // "" = apex
  type: string;
  answer: string;
  ttl: number;
  priority?: number;
};

/** Read-only view used by the DNS UI: apex host shown as "@". */
export type DnsHost = { name: string; type: string; address: string; ttl: number; mxPref?: number };

export type UrlForward = { host: string; forwardsTo: string; type: string };

/**
 * One registrar backend. Every method mirrors a `lib/registrar.ts` export
 * 1:1 (see that file's doc comments for the full behavioral contract each one
 * must honor — timeouts, `RegistrarError` on failure, SANDBOX synthetic
 * behavior for transfers, etc). A registrar that cannot yet support a given
 * capability (e.g. Namecheap before real credentials exist) still implements
 * every method — it just throws a `RegistrarError` with a clear "not
 * configured" message, exactly like `lib/registrar.ts`'s own `nc()` does today
 * when `NAMECOM_USERNAME`/`NAMECOM_TOKEN` are unset.
 */
export interface RegistrarClient {
  /** DB/dispatch id — e.g. "namecom", "namecheap". Never shown to a customer. */
  readonly id: string;
  /** Admin-display-only human name — e.g. "name.com", "Namecheap". NEVER pass to a customer-facing function or string. */
  readonly label: string;

  /** Are this registrar's credentials present in the environment? */
  configured(): boolean;

  checkDomains(domains: string[]): Promise<DomainCheck[]>;
  registerDomain(
    domain: string,
    years: number,
    contact: RegistrantContact,
    purchaseCents: number
  ): Promise<{ expiresAt?: Date }>;
  renewDomain(domain: string, years: number, purchaseCents: number): Promise<void>;
  domainInfo(domain: string): Promise<{ expires?: Date; created?: Date }>;
  /**
   * Disable the REGISTRAR'S OWN auto-renew flag on a just-registered/renewed
   * domain (see `lib/registrar.ts`'s doc comment on the name.com equivalent for
   * why this matters — a registrar renewing independently on its own schedule
   * would charge Nxeon's reseller balance regardless of the customer's choice).
   * Best-effort: must never throw in a way that unwinds an already-successful
   * registration/renewal.
   */
  disableRegistrarAutorenew(domain: string): Promise<void>;

  // ---- Nameservers / registrar lock / outbound-transfer auth code ----
  setNameservers(domain: string, nameservers: string[]): Promise<void>;
  lockDomain(domain: string): Promise<void>;
  unlockDomain(domain: string): Promise<void>;
  isDomainLocked(domain: string): Promise<boolean>;
  /** EPP/auth code for an outbound transfer. Null when the registrar has none to give. */
  getAuthCode(domain: string): Promise<string | null>;

  // ---- Inbound transfers (transfer-in) ----
  checkTransfer(domain: string): Promise<TransferCheck>;
  createTransfer(domain: string, authCode: string, purchaseCents: number): Promise<TransferInfo>;
  getTransfer(domain: string, startedAt?: Date | null): Promise<TransferInfo | null>;
  cancelTransfer(domain: string): Promise<TransferInfo>;
  /** All inbound transfers on this registrar's account (ops/debug — not used per-domain). */
  listTransfers(): Promise<TransferInfo[]>;

  // ---- DNS ----
  listRecords(domain: string): Promise<DnsRecord[]>;
  addRecord(
    domain: string,
    rec: { host: string; type: string; answer: string; ttl?: number; priority?: number }
  ): Promise<void>;
  deleteRecord(domain: string, id: number | string): Promise<void>;
  getDnsHosts(domain: string): Promise<DnsHost[]>;

  // ---- URL forwarding ----
  listUrlForwarding(domain: string): Promise<UrlForward[]>;
  addUrlForwarding(domain: string, fwd: UrlForward): Promise<void>;
  deleteUrlForwarding(domain: string, host: string): Promise<void>;
}

/**
 * Namecheap API client — the second `RegistrarClient` implementation
 * alongside name.com (`lib/registrar.ts`). Namecheap's API is XML over plain
 * query-string HTTP (this client POSTs the same params as a form body instead
 * of a query string, to avoid any URL-length limit on a `setHosts` call for a
 * domain with many DNS records — Namecheap's API treats GET and POST
 * identically). Parsed with `fast-xml-parser` (already a dependency).
 *
 * NOT LIVE YET. `NAMECHEAP_API_USER` / `NAMECHEAP_USERNAME` are blank in
 * `.env` as of this writing (Namecheap requires ApiUser + ApiKey + UserName +
 * ClientIp on every call), so `namecheapConfigured()` returns false and this
 * client is inert. Separately, Namecheap only accepts calls from an IP
 * explicitly whitelisted in the account's own dashboard (Profile → Tools →
 * Business & Dev Tools → API Access → Whitelisted IPs) — there is no API to
 * do this remotely, it's a manual step only the account owner can do. Even
 * once all three env vars are filled in, every real call will fail with an
 * IP-not-whitelisted error until `NAMECHEAP_CLIENT_IP` (51.79.162.96) is
 * whitelisted there by hand. See `lib/settings.ts`'s `registrar_namecheap_enabled`
 * kill-switch, defaulted OFF, for the separate "don't go live until an admin
 * has verified it end-to-end" gate.
 *
 * DOCUMENTATION SOURCES (developer.namecheap.com and www.namecheap.com/support/api
 * returned HTTP 403 to this agent's fetcher — likely bot-blocked — so every
 * endpoint/param/response shape below was verified via Google's cache of those
 * same official pages, Namecheap's own official example XML/URLs quoted in
 * those cached pages, and Namecheap's own official Go SDK
 * (github.com/namecheap/go-namecheap-sdk) and PHP SDK
 * (github.com/namecheap/namecheap-php-sdk) for cross-checking parameter names.
 * NOT guessed from memory. Specific gaps Namecheap's own docs do not resolve
 * are called out inline where they matter (see `getAuthCode`, `cancelTransfer`,
 * `disableRegistrarAutorenew`).
 */

import { XMLParser } from "fast-xml-parser";
import { RegistrarError, domainMarkupPct, retailCents } from "../registrar";
import type {
  DomainCheck,
  RegistrantContact,
  TransferCheck,
  TransferInfo,
  DnsRecord,
  DnsHost,
  UrlForward,
} from "./types";

const REGISTRAR_ID = "namecheap";

// ---------- Config / auth ----------

function apiUser(): string {
  return (process.env.NAMECHEAP_API_USER ?? "").trim();
}
function apiKey(): string {
  return (process.env.NAMECHEAP_API_KEY ?? "").trim();
}
function userName(): string {
  return (process.env.NAMECHEAP_USERNAME ?? "").trim();
}
function clientIp(): string {
  return (process.env.NAMECHEAP_CLIENT_IP ?? "").trim();
}

/** All 4 auth values Namecheap requires on every call are present. */
export function namecheapConfigured(): boolean {
  return !!(apiUser() && apiKey() && userName() && clientIp());
}

/**
 * Sandbox vs. production base URL — gated the same defensive way
 * `lib/paypal.ts` gates Stripe/PayPal live mode: an ambiguous/unset value
 * NEVER silently resolves to live. `NAMECHEAP_SANDBOX` is explicit-opt-out
 * (only a recognized "off" value selects production), mirroring the variable
 * the .env file already defines rather than inventing a second one.
 *
 * Base URLs confirmed against Namecheap's official SDKs (both the Go SDK and
 * the widely-used PyNamecheap client hardcode these two hosts):
 *   sandbox:    https://api.sandbox.namecheap.com/xml.response
 *   production: https://api.namecheap.com/xml.response
 */
function namecheapSandbox(): boolean {
  const raw = (process.env.NAMECHEAP_SANDBOX ?? "").trim().toLowerCase();
  if (raw === "0" || raw === "false" || raw === "live" || raw === "production") return false;
  if (raw === "1" || raw === "true" || raw === "sandbox") return true;
  // Ambiguous or unset — the safe default is sandbox, never live.
  return true;
}

function apiBase(): string {
  return namecheapSandbox() ? "https://api.sandbox.namecheap.com/xml.response" : "https://api.namecheap.com/xml.response";
}

// ---------- HTTP + XML plumbing ----------

const xmlParser = new XMLParser({ ignoreAttributes: false, attributeNamePrefix: "" });

const asArray = <T>(x: T | T[] | undefined | null): T[] => (x === undefined || x === null ? [] : Array.isArray(x) ? x : [x]);

/** `"12.34"` (or a number) -> 1234. `undefined`/`""`/non-numeric -> null. Never guesses a price. */
function dollarsToCents(d: unknown): number | null {
  if (d === undefined || d === null || d === "") return null;
  const n = Number(d);
  return Number.isFinite(n) ? Math.round(n * 100) : null;
}

/** Namecheap dates are MM/DD/YYYY (confirmed against `domains.getInfo`'s own example response). */
function parseNcDate(s: unknown): Date | undefined {
  if (typeof s !== "string") return undefined;
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(s.trim());
  if (!m) return undefined;
  const d = new Date(Date.UTC(Number(m[3]), Number(m[1]) - 1, Number(m[2])));
  return Number.isNaN(d.getTime()) ? undefined : d;
}

/** "example.co.uk" -> { sld: "example", tld: "co.uk" }. Namecheap's DNS/nameserver commands take SLD+TLD separately rather than one domain string. */
function splitDomain(domain: string): { sld: string; tld: string } {
  const dot = domain.indexOf(".");
  return dot < 0 ? { sld: domain, tld: "" } : { sld: domain.slice(0, dot), tld: domain.slice(dot + 1) };
}

/**
 * POST one Namecheap command and return its parsed `CommandResponse` node.
 * Throws a `RegistrarError` (registrarId "namecheap") on transport failure,
 * an unparseable body, or `ApiResponse Status="ERROR"`.
 */
async function nc(command: string, params: Record<string, string>): Promise<any> {
  if (!namecheapConfigured()) throw new RegistrarError(REGISTRAR_ID, "registrar is not configured");
  const body = new URLSearchParams({
    ApiUser: apiUser(),
    ApiKey: apiKey(),
    UserName: userName(),
    ClientIp: clientIp(),
    Command: command,
    ...params,
  });
  const res = await fetch(apiBase(), {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: body.toString(),
    signal: AbortSignal.timeout(30_000),
  });
  const text = await res.text();
  let parsed: any;
  try {
    parsed = xmlParser.parse(text);
  } catch {
    throw new RegistrarError(REGISTRAR_ID, `unparseable response (HTTP ${res.status})`);
  }
  const api = parsed?.ApiResponse;
  if (!api) throw new RegistrarError(REGISTRAR_ID, `unexpected response shape (HTTP ${res.status})`);
  if (String(api.Status).toUpperCase() !== "OK") {
    const errs = asArray(api?.Errors?.Error).map((e: any) => (typeof e === "object" ? String(e["#text"] ?? "") : String(e)));
    throw new RegistrarError(REGISTRAR_ID, errs.filter(Boolean).join("; ") || `namecheap API error (HTTP ${res.status})`);
  }
  return api.CommandResponse;
}

// ---------- TLD pricing (users.getPricing) ----------
//
// Unlike name.com's `domains:checkAvailability` (which returns a price inline
// per domain), Namecheap's `domains.check` returns NO price for an ordinary
// (non-premium) name — only `IsPremiumName`/`Premium*Price` for premium ones.
// Regular per-TLD register/renew/transfer pricing comes from a SEPARATE call,
// `namecheap.users.getPricing` (ProductType=DOMAIN), which returns the
// reseller's own contracted price for every TLD at once. That price list
// changes rarely, so it's fetched once per action type and cached in-process.

type NcTldPricing = { registerCents: number | null; renewCents: number | null; transferCents: number | null };

const PRICING_TTL_MS = 6 * 60 * 60 * 1000; // 6h — a reseller price list, not a live quote.
let pricingCache: { at: number; map: Map<string, NcTldPricing> } | null = null;

async function fetchTldPrices(actionType: "REGISTER" | "RENEW" | "TRANSFER"): Promise<Map<string, number>> {
  const cr = await nc("namecheap.users.getPricing", { ProductType: "DOMAIN", ActionType: actionType });
  const out = new Map<string, number>();
  for (const pt of asArray(cr?.UserGetPricingResult?.ProductType)) {
    for (const cat of asArray(pt?.ProductCategory)) {
      for (const prod of asArray(cat?.Product)) {
        const tld = String(prod?.Name ?? "").toLowerCase();
        if (!tld) continue;
        const prices = asArray(prod?.Price);
        const oneYear = prices.find((p: any) => String(p?.Duration) === "1" && String(p?.DurationType).toUpperCase() === "YEAR") ?? prices[0];
        if (!oneYear) continue;
        const cents = dollarsToCents(oneYear.YourPrice ?? oneYear.Price ?? oneYear.RegularPrice);
        if (cents !== null) out.set(tld, cents);
      }
    }
  }
  return out;
}

/** Cached `{register, renew, transfer}` cost-in-cents per TLD, keyed lowercase without the leading dot. */
async function tldPricingMap(): Promise<Map<string, NcTldPricing>> {
  const now = Date.now();
  if (pricingCache && now - pricingCache.at < PRICING_TTL_MS) return pricingCache.map;
  const [register, renew, transfer] = await Promise.all([
    fetchTldPrices("REGISTER"),
    fetchTldPrices("RENEW"),
    fetchTldPrices("TRANSFER"),
  ]);
  const map = new Map<string, NcTldPricing>();
  for (const tld of new Set([...register.keys(), ...renew.keys(), ...transfer.keys()])) {
    map.set(tld, {
      registerCents: register.get(tld) ?? null,
      renewCents: renew.get(tld) ?? null,
      transferCents: transfer.get(tld) ?? null,
    });
  }
  pricingCache = { at: now, map };
  return map;
}

// ---------- Availability / pricing ----------

export async function checkDomains(domains: string[]): Promise<DomainCheck[]> {
  if (domains.length === 0) return [];
  const cr = await nc("namecheap.domains.check", { DomainList: domains.join(",") });
  const pct = await domainMarkupPct();
  const pricing = await tldPricingMap();
  return asArray(cr?.DomainCheckResult).map((r: any) => {
    const domain = String(r?.Domain ?? "").toLowerCase();
    const available = String(r?.Available).toLowerCase() === "true";
    const premium = String(r?.IsPremiumName).toLowerCase() === "true";
    let costCents: number | null;
    let renewCostCents: number | null;
    if (premium) {
      costCents = dollarsToCents(r?.PremiumRegistrationPrice);
      renewCostCents = dollarsToCents(r?.PremiumRenewalPrice);
    } else {
      const tld = domain.slice(domain.indexOf(".") + 1);
      const p = pricing.get(tld);
      costCents = p?.registerCents ?? null;
      renewCostCents = p?.renewCents ?? null;
    }
    return {
      domain,
      available,
      premium,
      priceCents: retailCents(costCents, pct),
      costCents,
      renewCents: retailCents(renewCostCents, pct),
    };
  });
}

// ---------- Register / renew / info ----------

function ncContactParams(prefix: string, c: RegistrantContact): Record<string, string> {
  return {
    [`${prefix}FirstName`]: c.firstName,
    [`${prefix}LastName`]: c.lastName,
    [`${prefix}Address1`]: c.address1,
    [`${prefix}City`]: c.city,
    [`${prefix}StateProvince`]: c.stateProvince,
    [`${prefix}PostalCode`]: c.postalCode,
    [`${prefix}Country`]: c.country,
    [`${prefix}Phone`]: c.phone,
    [`${prefix}EmailAddress`]: c.email,
  };
}

/**
 * Namecheap has no documented per-request "expected price" parameter the way
 * name.com's `purchasePrice` does — it always charges the account's own
 * contracted rate from the reseller balance. `purchaseCents` is accepted for
 * `RegistrarClient` interface parity only; a caller that needs a price guard
 * must compare its own frozen quote against a fresh `checkDomains()` call
 * BEFORE calling `registerDomain`/`renewDomain`/`createTransfer`, not rely on
 * this client to enforce it server-side.
 */
export async function registerDomain(
  domain: string,
  years: number,
  contact: RegistrantContact,
  purchaseCents: number
): Promise<{ expiresAt?: Date }> {
  void purchaseCents;
  const cr = await nc("namecheap.domains.create", {
    DomainName: domain,
    Years: String(years),
    AddFreeWhoisguard: "yes",
    WGEnabled: "yes",
    ...ncContactParams("Registrant", contact),
    ...ncContactParams("Tech", contact),
    ...ncContactParams("Admin", contact),
    ...ncContactParams("AuxBilling", contact),
  });
  const result = cr?.DomainCreateResult;
  if (!result || String(result.Registered).toLowerCase() !== "true") {
    throw new RegistrarError(REGISTRAR_ID, `registration did not confirm success: ${JSON.stringify(result ?? {}).slice(0, 200)}`);
  }
  await disableRegistrarAutorenew(domain);
  return {};
}

export async function renewDomain(domain: string, years: number, purchaseCents: number): Promise<void> {
  void purchaseCents; // see registerDomain's note above.
  await nc("namecheap.domains.renew", { DomainName: domain, Years: String(years) });
  await disableRegistrarAutorenew(domain);
}

export async function domainInfo(domain: string): Promise<{ expires?: Date; created?: Date }> {
  const cr = await nc("namecheap.domains.getInfo", { DomainName: domain });
  const details = cr?.DomainGetInfoResult?.DomainDetails;
  return { expires: parseNcDate(details?.ExpiredDate), created: parseNcDate(details?.CreatedDate) };
}

/**
 * REAL GAP, not a bug in this client: unlike name.com's documented
 * `:disableAutorenew` endpoint, Namecheap's public API has no command to
 * toggle a domain's own auto-renew flag — it is only exposed in the account
 * dashboard's per-domain settings. Logged (never thrown — must not undo an
 * already-successful registration/renewal) so a Namecheap-sourced domain's
 * own auto-renew setting doesn't silently diverge from what the customer
 * chose in this platform without anyone noticing.
 */
export async function disableRegistrarAutorenew(domain: string): Promise<void> {
  console.error(
    `[registrar:namecheap] no API exists to disable Namecheap's own auto-renew for ${domain} — verify/disable it manually in the Namecheap dashboard, or via a future domains.getList "AutoRenew" reconciliation sweep`
  );
}

// ---------- Nameservers / registrar lock / auth code ----------

export async function setNameservers(domain: string, nameservers: string[]): Promise<void> {
  const { sld, tld } = splitDomain(domain);
  await nc("namecheap.domains.dns.setCustom", { SLD: sld, TLD: tld, NameServers: nameservers.join(",") });
}

export async function lockDomain(domain: string): Promise<void> {
  await nc("namecheap.domains.setRegistrarLock", { DomainName: domain, LockAction: "lock" });
}

export async function unlockDomain(domain: string): Promise<void> {
  await nc("namecheap.domains.setRegistrarLock", { DomainName: domain, LockAction: "unlock" });
}

export async function isDomainLocked(domain: string): Promise<boolean> {
  const cr = await nc("namecheap.domains.getRegistrarLock", { DomainName: domain });
  return String(cr?.DomainGetRegistrarLockResult?.RegistrarLockStatus).toLowerCase() === "true";
}

/**
 * REAL GAP: Namecheap's API has no documented method to return a domain's
 * EPP/auth code. It is only obtainable through the account dashboard's "Get
 * EPP code" flow, which EMAILS the code to the account holder rather than
 * returning it in any API response. Returning `null` (rather than inventing
 * an endpoint) matches this function's own documented contract — "Null when
 * the registrar has none to give."
 */
export async function getAuthCode(domain: string): Promise<string | null> {
  console.error(`[registrar:namecheap] no API exists to fetch an EPP/auth code for ${domain} — use the Namecheap dashboard's "Get EPP code" flow`);
  return null;
}

// ---------- Inbound transfers ----------

export async function checkTransfer(domain: string): Promise<TransferCheck> {
  const cr = await nc("namecheap.domains.check", { DomainList: domain });
  const r = asArray(cr?.DomainCheckResult)[0];
  if (!r) {
    return { domain, transferable: false, reason: "We couldn't look this domain up at the registrar. Check the spelling and try again.", premium: false, priceCents: null, costCents: null };
  }
  const available = String(r.Available).toLowerCase() === "true";
  const premium = String(r.IsPremiumName).toLowerCase() === "true";
  if (available) {
    return { domain, transferable: false, reason: "This domain isn't registered anywhere yet, so there's nothing to transfer — register it instead.", premium, priceCents: null, costCents: null };
  }
  if (premium) {
    return { domain, transferable: false, reason: "Premium domains can't be transferred in automatically — contact support.", premium: true, priceCents: null, costCents: null };
  }
  const tld = domain.slice(domain.indexOf(".") + 1).toLowerCase();
  const pricing = await tldPricingMap();
  const entry = pricing.get(tld);
  // Prefer Namecheap's own published TRANSFER price; a transfer also always
  // includes a 1-year extension, so the renewal rate is the honest fallback
  // when a TLD has no distinct transfer price listed (mirrors name.com's
  // identical fallback reasoning in lib/registrar.ts's transferCostCents).
  const cost = entry?.transferCents ?? entry?.renewCents ?? null;
  if (cost === null) {
    return { domain, transferable: false, reason: "We can't get a transfer price for this TLD from the registrar right now — contact support.", premium: false, priceCents: null, costCents: null };
  }
  const pct = await domainMarkupPct();
  return { domain, transferable: true, reason: null, premium: false, priceCents: retailCents(cost, pct), costCents: cost };
}

export async function createTransfer(domain: string, authCode: string, purchaseCents: number): Promise<TransferInfo> {
  void purchaseCents; // see registerDomain's note.
  await nc("namecheap.domains.transfer.create", { DomainName: domain, EPPCode: authCode, Years: "1" });
  // `domains.transfer.create`'s own response carries no human-readable status
  // string (only numeric StatusID/StatusCode) — `domains.transfer.getList`
  // does, so fetch it immediately for a status the customer can read.
  const info = await getTransfer(domain).catch(() => null);
  return info ?? { domain, status: "submitted", email: null };
}

export async function getTransfer(domain: string, _startedAt?: Date | null): Promise<TransferInfo | null> {
  void _startedAt; // Namecheap has no sandbox-synthetic transfer timeline to drive off this (see file header).
  const cr = await nc("namecheap.domains.transfer.getList", { PageSize: "100" });
  const match = asArray(cr?.TransferGetListResult?.Transfer).find(
    (t: any) => String(t?.Domainname ?? "").toLowerCase() === domain.toLowerCase()
  );
  if (!match) return null;
  // Namecheap's transfer list has no equivalent of name.com's "losing
  // registrar sent the approval email to this address" field.
  return { domain, status: String(match.Status ?? match.StatusDescription ?? "pending"), email: null };
}

/**
 * REAL GAP: Namecheap's documented transfer API surface is create / getStatus
 * / getList / updateStatus — there is no `cancel` command. A pending inbound
 * transfer can only be cancelled by contacting Namecheap support directly.
 * Throwing here (rather than reporting a false "cancelled") matches this
 * client's "never fabricate a status" rule.
 */
export async function cancelTransfer(domain: string): Promise<TransferInfo> {
  throw new RegistrarError(REGISTRAR_ID, `Namecheap's API has no way to cancel an inbound transfer for ${domain} — this must be cancelled by contacting Namecheap support directly`);
}

export async function listTransfers(): Promise<TransferInfo[]> {
  const cr = await nc("namecheap.domains.transfer.getList", { PageSize: "100" });
  return asArray(cr?.TransferGetListResult?.Transfer).map((t: any) => ({
    domain: String(t?.Domainname ?? ""),
    status: String(t?.Status ?? t?.StatusDescription ?? "pending"),
    email: null,
  }));
}

// ---------- DNS ----------
//
// Namecheap's DNS API is REPLACE-ALL, not per-record CRUD: the only write
// command, `domains.dns.setHosts`, takes the COMPLETE desired host list every
// time (numbered HostName1/RecordType1/Address1/TTL1/MXPref1... params) —
// there is no name.com-style "add one record" / "delete record {id}". Every
// add/delete below is therefore a read-modify-write (`listRecords` then
// `setHosts` with the full, modified list), which is NOT atomic against a
// concurrent edit the way name.com's per-record endpoints are — a real
// structural difference from name.com worth remembering if two DNS edits for
// the same domain could ever race.

async function writeHosts(domain: string, records: DnsRecord[]): Promise<void> {
  const { sld, tld } = splitDomain(domain);
  const params: Record<string, string> = { SLD: sld, TLD: tld };
  records.forEach((r, i) => {
    const n = i + 1;
    params[`HostName${n}`] = r.host === "" ? "@" : r.host;
    params[`RecordType${n}`] = r.type;
    params[`Address${n}`] = r.answer;
    params[`TTL${n}`] = String(r.ttl || 1800);
    if (r.priority !== undefined) params[`MXPref${n}`] = String(r.priority);
  });
  await nc("namecheap.domains.dns.setHosts", params);
}

export async function listRecords(domain: string): Promise<DnsRecord[]> {
  const { sld, tld } = splitDomain(domain);
  const cr = await nc("namecheap.domains.dns.getHosts", { SLD: sld, TLD: tld });
  return asArray(cr?.DomainDNSGetHostsResult?.Host).map((h: any) => ({
    id: String(h?.HostId ?? ""),
    host: String(h?.Name ?? "") === "@" ? "" : String(h?.Name ?? ""),
    type: String(h?.Type ?? ""),
    answer: String(h?.Address ?? ""),
    ttl: Number(h?.TTL ?? 1800) || 1800,
    priority: h?.MXPref !== undefined ? Number(h.MXPref) : undefined,
  }));
}

export async function addRecord(
  domain: string,
  rec: { host: string; type: string; answer: string; ttl?: number; priority?: number }
): Promise<void> {
  const existing = await listRecords(domain);
  await writeHosts(domain, [
    ...existing,
    { id: "", host: rec.host, type: rec.type, answer: rec.answer, ttl: rec.ttl ?? 1800, priority: rec.priority },
  ]);
}

export async function deleteRecord(domain: string, id: number | string): Promise<void> {
  const existing = await listRecords(domain);
  const remaining = existing.filter((r) => String(r.id) !== String(id));
  // Already gone — matches name.com's `nullOn404` tolerance for a record that
  // dropped off the list between the caller's read and this delete.
  if (remaining.length === existing.length) return;
  await writeHosts(domain, remaining);
}

/** Read-only view used by the DNS UI: apex host shown as "@", forwarding record types excluded (see listUrlForwarding). */
export async function getDnsHosts(domain: string): Promise<DnsHost[]> {
  const recs = await listRecords(domain);
  return recs
    .filter((r) => r.type !== "URL301" && r.type !== "URL" && r.type !== "FRAME")
    .map((r) => ({ name: r.host === "" ? "@" : r.host, type: r.type, address: r.answer, ttl: r.ttl, mxPref: r.priority }));
}

// ---------- URL forwarding ----------
//
// Namecheap has no separate URL-forwarding CRUD endpoint like name.com's
// `/url/forwarding` — forwarding is implemented as ordinary host records with
// RecordType "URL301" (permanent redirect) or "URL" (masked/302-style), set
// through the SAME `dns.setHosts` replace-all call as every other record.

function isForwardRecord(r: DnsRecord): boolean {
  return r.type === "URL301" || r.type === "URL";
}

export async function listUrlForwarding(domain: string): Promise<UrlForward[]> {
  const recs = await listRecords(domain);
  return recs.filter(isForwardRecord).map((r) => ({ host: r.host, forwardsTo: r.answer, type: r.type === "URL301" ? "redirect301" : "redirect302" }));
}

export async function addUrlForwarding(domain: string, fwd: UrlForward): Promise<void> {
  const recordType = fwd.type === "redirect301" ? "URL301" : "URL";
  const existing = await listRecords(domain);
  const withoutSameHost = existing.filter((r) => !(isForwardRecord(r) && r.host === fwd.host));
  await writeHosts(domain, [...withoutSameHost, { id: "", host: fwd.host, type: recordType, answer: fwd.forwardsTo, ttl: 1800 }]);
}

export async function deleteUrlForwarding(domain: string, host: string): Promise<void> {
  const existing = await listRecords(domain);
  const remaining = existing.filter((r) => !(isForwardRecord(r) && r.host === host));
  if (remaining.length === existing.length) return;
  await writeHosts(domain, remaining);
}

