export const ALL_REGISTRARS: readonly RegistrarClient[] = [NameComRegistrar, NamecheapRegistrar];

/** Look up a specific registrar by its DB/dispatch id ("namecom" / "namecheap"). */
export function registrarById(id: string): RegistrarClient | undefined {
  return ALL_REGISTRARS.find((r) => r.id === id);
}

/**
 * Registrars available for a NEW quote/search right now: env-configured
 * (`RegistrarClient.configured()`) AND admin-enabled (`registrar_<id>_enabled`
 * setting — see lib/settings.ts). Both gates must pass; neither alone is
 * enough. Order is `ALL_REGISTRARS`' order, not price order — callers that
 * care about cheapest (lib/tools/domain-availability.ts) sort themselves.
 */
export async function configuredRegistrars(): Promise<RegistrarClient[]> {
  const [namecomEnabled, namecheapEnabled] = await Promise.all([
    getSettingBool("registrar_namecom_enabled", true),
    getSettingBool("registrar_namecheap_enabled", false),
  ]);
  const enabledById: Record<string, boolean> = { namecom: namecomEnabled, namecheap: namecheapEnabled };
  return ALL_REGISTRARS.filter((r) => r.configured() && (enabledById[r.id] ?? false));
}

