input.content:
/**
 * Batched, cached, globally-throttled, MULTI-REGISTRAR availability lookups
 * for the public domain-name generator and the signed-in domain wizard.
 *
 * Each configured registrar (`lib/registrars/index.ts`'s `configuredRegistrars()`
 * — env-configured AND admin-enabled) is a METERED third-party API, so three
 * protections sit in front of EACH one independently:
 *
 *   1. CACHE     — a short-TTL in-process map keyed by `(registrarId, domain)`,
 *                  since two registrars quoting the same domain are two
 *                  different facts, not one.
 *   2. BATCHING  — each registrar's `checkDomains` takes an array, so a whole
 *                  page of candidates is as few upstream calls as that
 *                  registrar's own real per-call limit allows (see
 *                  `BATCH_SIZE_BY_REGISTRAR` below — verified per registrar,
 *                  never assumed to match another).
 *   3. GLOBAL CAP — a process-wide sliding window PER REGISTRAR
 *                  (`registrar:availability:<id>:global`), so one registrar's
 *                  outage/slowness/rate-limit can never throttle the others.
 *
 * MERGE: for each domain, the cheapest `available: true` result across
 * registrars wins; a domain is "taken" only if at least one registrar
 * explicitly says so; "unknown" only when EVERY registrar came back unknown
 * (down, throttled, or simply not configured at all). Registrar identity
 * never appears on the merged result — `DomainResult` carries no registrar
 * id, by construction, so it cannot leak into the client bundle (see
 * `test/registrar-leak-guard.test.ts`).
 *
 * Prices are only ever what a registrar actually returned. When neither
 * registrar gives us a price we surface no price — never an estimate, never a
 * TLD average.
 */

import { checkRateLimit } from "@/lib/rate-limit";
import { configuredRegistrars, type DomainCheck, type RegistrarClient } from "@/lib/registrars";

/**
 * Max domains sent in a single upstream `checkDomains` call, PER REGISTRAR.
 *
 * name.com: verified working at 24 (see git history — this repo's own prior
 * single-registrar constant). Namecheap: its API docs do not publish a
 * documented maximum for `domains.check`'s comma-separated `DomainList` (only
 * an overall 50 calls/min · 700/hour · 8000/day per-key rate limit is
 * documented) — 20 is a deliberately conservative choice pending real-world
 * verification once Namecheap can actually authenticate (see
 * lib/registrars/namecheap.ts's file header for why it can't yet). Do NOT
 * assume this number is confirmed the way name.com's is.
 */
const BATCH_SIZE_BY_REGISTRAR: Record<string, number> = {
  namecom: 24,
  namecheap: 20,
};
const DEFAULT_BATCH_SIZE = 20;

/** Cache lifetime. Long enough to absorb re-rolls, short enough to stay honest. */
const CACHE_TTL_MS = 10 * 60 * 1000;

/** Hard ceiling on entries so the map can't grow unbounded. */
const CACHE_MAX = 4000;

/** Process-wide registrar budget: batches per minute across ALL visitors, PER REGISTRAR. */
const GLOBAL_BATCHES_PER_MIN = 60;

type Entry = { at: number; check: DomainCheck };

/** Cache key: `(registrarId, domain)` — two registrars quoting the same domain are two different facts. */
const cacheKey = (registrarId: string, domain: string) => `${registrarId}:${domain}`;

const localCache = new Map<string, Entry>();
// Survive HMR / route reloads in dev so the cache actually caches.
const globalForCache = globalThis as unknown as { __nxeonDomainAvail?: Map<string, Entry> };
const cache: Map<string, Entry> = globalForCache.__nxeonDomainAvail ?? localCache;
if (process.env.NODE_ENV !== "production") globalForCache.__nxeonDomainAvail = cache;

function readCache(registrarId: string, domain: string, now: number): DomainCheck | null {
  const key = cacheKey(registrarId, domain);
  const hit = cache.get(key);
  if (!hit) return null;
  if (now - hit.at > CACHE_TTL_MS) {
    cache.delete(key);
    return null;
  }
  return hit.check;
}

function writeCache(registrarId: string, check: DomainCheck, now: number): void {
  if (cache.size >= CACHE_MAX) {
    // Drop the oldest ~10% rather than clearing everything on a cold spike.
    const victims = [...cache.entries()]
      .sort((a, b) => a[1].at - b[1].at)
      .slice(0, Math.ceil(CACHE_MAX / 10));
    for (const [k] of victims) cache.delete(k);
  }
  cache.set(cacheKey(registrarId, check.domain), { at: now, check });
}

export type AvailabilityStatus = "available" | "taken" | "unknown";

export type DomainResult = {
  domain: string;
  status: AvailabilityStatus;
  premium: boolean;
  /** Retail first-year price in integer cents, or null when no registrar gave one. */
  priceCents: number | null;
  /** Retail renewal price in integer cents, or null. */
  renewCents: number | null;
};

export type AvailabilityOutcome = {
  results: DomainResult[];
  /** False when NO registrar is configured+enabled at all — everything is "unknown". */
  configured: boolean;
  /** True when at least one registrar's lookup was skipped to protect its shared upstream budget. */
  throttled: boolean;
  /** How many (registrar, domain) lookups were served from cache rather than a registrar. */
  cached: number;
};

function toResult(check: DomainCheck): DomainResult {
  // A registrar only prices a purchasable name; a taken domain comes back priceless.
  const available = check.available && check.priceCents !== null;
  return {
    domain: check.domain,
    status: available ? "available" : "taken",
    premium: check.premium,
    priceCents: available ? check.priceCents : null,
    renewCents: available ? check.renewCents : null,
  };
}

function unknown(domain: string): DomainResult {
  return { domain, status: "unknown", premium: false, priceCents: null, renewCents: null };
}

/**
 * Merge one domain's per-registrar results into the single result the
 * customer sees. Pure and exported for testing — this is the one place
 * "which registrar's price wins" is decided.
 *
 *   - At least one "available" (with a price) -> "available", cheapest price wins.
 *   - Else at least one "taken" -> "taken" (a registry-sync disagreement never
 *     shows a domain as available if even one registrar says it's gone).
 *   - Else -> "unknown" (every registrar was down/throttled/unconfigured) —
 *     never fabricated as available or taken.
 *
 * `results` must be non-empty; each entry ideally already carries `domain`
 * matching the domain being merged (not checked here — the caller guarantees it).
 */
export function mergeCheapest(domain: string, results: DomainResult[]): DomainResult {
  const available = results.filter((r) => r.status === "available" && r.priceCents !== null);
  if (available.length > 0) {
    return available.reduce((best, r) => (r.priceCents! < best.priceCents! ? r : best));
  }
  if (results.some((r) => r.status === "taken")) {
    // Prefer a "taken" entry's own shape (e.g. its `premium` flag) over a synthesized one.
    return results.find((r) => r.status === "taken") ?? { domain, status: "taken", premium: false, priceCents: null, renewCents: null };
  }
  return unknown(domain);
}

/** One registrar's resolved results for a batch of domains, plus its own throttle/cache stats. */
async function resolveForRegistrar(
  registrar: RegistrarClient,
  domains: string[],
  now: number
): Promise<{ results: Map<string, DomainResult>; throttled: boolean; cached: number }> {
  const resolved = new Map<string, DomainResult>();
  const misses: string[] = [];
  for (const d of domains) {
    const hit = readCache(registrar.id, d, now);
    if (hit) resolved.set(d, toResult(hit));
    else misses.push(d);
  }
  const cached = resolved.size;

  let throttled = false;
  const batchSize = BATCH_SIZE_BY_REGISTRAR[registrar.id] ?? DEFAULT_BATCH_SIZE;
  const batches: string[][] = [];
  for (let i = 0; i < misses.length; i += batchSize) batches.push(misses.slice(i, i + batchSize));

  for (const batch of batches) {
    // Shared upstream budget — checked per batch, not per domain, PER REGISTRAR
    // so one registrar's outage/rate-limit can't throttle the others.
    const budget = checkRateLimit(`registrar:availability:${registrar.id}:global`, {
      max: GLOBAL_BATCHES_PER_MIN,
      windowMs: 60_000,
    });
    if (!budget.ok) {
      throttled = true;
      for (const d of batch) resolved.set(d, unknown(d));
      continue;
    }

    try {
      const checks = await registrar.checkDomains(batch);
      const seen = new Set<string>();
      for (const check of checks) {
        const key = check.domain.toLowerCase();
        seen.add(key);
        writeCache(registrar.id, { ...check, domain: key }, now);
        resolved.set(key, toResult(check));
      }
      // A domain this registrar simply didn't answer for stays honest.
      for (const d of batch) if (!seen.has(d)) resolved.set(d, unknown(d));
    } catch {
      for (const d of batch) resolved.set(d, unknown(d));
    }
  }

  return { results: resolved, throttled, cached };
}

/**
 * Look up availability for a list of domains, preserving input order, fanned
 * out across every configured+enabled registrar and merged to the cheapest
 * available price (see `mergeCheapest`).
 *
 * Never throws: a registrar outage degrades every uncached domain to `unknown`
 * so the page still renders names, clearly marked as unverified.
 */
export async function checkAvailabilityBatched(domains: string[]): Promise<AvailabilityOutcome> {
  const now = Date.now();
  const unique = [...new Set(domains.map((d) => d.toLowerCase()))];

  const registrars = await configuredRegistrars();
  if (registrars.length === 0) {
    return { results: unique.map(unknown), configured: false, throttled: false, cached: 0 };
  }

  const perRegistrar = await Promise.all(registrars.map((r) => resolveForRegistrar(r, unique, now)));

  let throttled = false;
  let cached = 0;
  for (const outcome of perRegistrar) {
    throttled = throttled || outcome.throttled;
    cached += outcome.cached;
  }

  const results = unique.map((d) => {
    const candidates = perRegistrar.map((o) => o.results.get(d) ?? unknown(d));
    return mergeCheapest(d, candidates);
  });

  return { results, configured: true, throttled, cached };
}

/** `$12.99` from integer cents. Returns null so callers can't print a fake price. */
export function formatPrice(cents: number | null): string | null {
  if (cents === null || !Number.isFinite(cents)) return null;
  return `$${(cents / 100).toFixed(2)}`;
}

