// ---------- Availability / pricing ----------

/** One `namecheap.domains.check` result, BEFORE markup — the registrar's own facts only. */
export type ParsedDomainCheck = {
  domain: string;
  available: boolean;
  premium: boolean;
  /** Registrar cost (cents) for premium names — `null` for an ordinary name (see `tldPricingMap`/`fetchTldPrices` instead). */
  premiumRegisterCents: number | null;
  premiumRenewCents: number | null;
};

/**
 * Pure parse of a `namecheap.domains.check` `CommandResponse` node into plain
 * data, no markup/pricing-lookup applied. Exported so it can be tested
 * directly against a realistic sample response body (fast-xml-parser's own
 * parsed shape) without needing `domainMarkupPct()`'s database read.
 */
export function parseCheckResponse(cr: any): ParsedDomainCheck[] {
  return asArray(cr?.DomainCheckResult).map((r: any) => {
    const domain = String(r?.Domain ?? "").toLowerCase();
    const premium = String(r?.IsPremiumName).toLowerCase() === "true";
    return {
      domain,
      available: String(r?.Available).toLowerCase() === "true",
      premium,
      premiumRegisterCents: premium ? dollarsToCents(r?.PremiumRegistrationPrice) : null,
      premiumRenewCents: premium ? dollarsToCents(r?.PremiumRenewalPrice) : null,
    };
  });
}

export async function checkDomains(domains: string[]): Promise<DomainCheck[]> {
  if (domains.length === 0) return [];
  const cr = await nc("namecheap.domains.check", { DomainList: domains.join(",") });
  const pct = await domainMarkupPct();
  const pricing = await tldPricingMap();
  return parseCheckResponse(cr).map((r) => {
    let costCents: number | null;
    let renewCostCents: number | null;
    if (r.premium) {
      costCents = r.premiumRegisterCents;
      renewCostCents = r.premiumRenewCents;
    } else {
      const tld = r.domain.slice(r.domain.indexOf(".") + 1);
      const p = pricing.get(tld);
      costCents = p?.registerCents ?? null;
      renewCostCents = p?.renewCents ?? null;
    }
    return {
      domain: r.domain,
      available: r.available,
      premium: r.premium,
      priceCents: retailCents(costCents, pct),
      costCents,
      renewCents: retailCents(renewCostCents, pct),
    };
  });
}

