import { test } from "node:test";
import assert from "node:assert/strict";
import { mergeCheapest, type DomainResult } from "../lib/tools/domain-availability.ts";

/**
 * `mergeCheapest` is the one place lib/tools/domain-availability.ts decides
 * which registrar's answer a customer actually sees, once more than one
 * registrar is configured. See that file's header comment for the full rule:
 * cheapest "available" wins; "taken" if any registrar says so; "unknown" only
 * if EVERY registrar came back unknown. Registrar identity never appears on
 * a `DomainResult` — these tests confirm the merge logic never needs it
 * either, which is what keeps it out of the client bundle by construction.
 */

const available = (priceCents: number, renewCents: number | null = null): DomainResult => ({
  domain: "example.com",
  status: "available",
  premium: false,
  priceCents,
  renewCents,
});
const taken = (): DomainResult => ({ domain: "example.com", status: "taken", premium: false, priceCents: null, renewCents: null });
const unknown = (): DomainResult => ({ domain: "example.com", status: "unknown", premium: false, priceCents: null, renewCents: null });

test("two registrars agree available — cheapest of two equal-ish quotes still resolves correctly", () => {
  const merged = mergeCheapest("example.com", [available(1099), available(1099)]);
  assert.equal(merged.status, "available");
  assert.equal(merged.priceCents, 1099);
});

test("registrars disagree on price — the cheaper AVAILABLE quote wins, regardless of which came first", () => {
  const cheaper = available(899, 1499);
  const pricier = available(1299, 1699);
  assert.equal(mergeCheapest("example.com", [pricier, cheaper]).priceCents, 899);
  assert.equal(mergeCheapest("example.com", [cheaper, pricier]).priceCents, 899);
  // The renewal price travels WITH the winning quote, not mixed from the other registrar.
  assert.equal(mergeCheapest("example.com", [pricier, cheaper]).renewCents, 1499);
});

test("one registrar says taken, the other says available — taken wins (registry-sync disagreement is never shown as available)", () => {
  const merged = mergeCheapest("example.com", [available(899), taken()]);
  assert.equal(merged.status, "taken");
});

test("taken wins even when the taken registrar was checked first", () => {
  const merged = mergeCheapest("example.com", [taken(), available(899)]);
  assert.equal(merged.status, "taken");
});

test("one registrar unknown, the other available — the available quote is used, not degraded to unknown", () => {
  const merged = mergeCheapest("example.com", [unknown(), available(1099)]);
  assert.equal(merged.status, "available");
  assert.equal(merged.priceCents, 1099);
});

test("one registrar unknown, the other taken — taken still wins over unknown", () => {
  const merged = mergeCheapest("example.com", [unknown(), taken()]);
  assert.equal(merged.status, "taken");
});

test("every registrar unknown — merged result is unknown, never fabricated as available or taken", () => {
  const merged = mergeCheapest("example.com", [unknown(), unknown()]);
  assert.equal(merged.status, "unknown");
  assert.equal(merged.priceCents, null);
});

test("a single registrar's result passes through unchanged", () => {
  const only = available(1250, 1799);
  const merged = mergeCheapest("example.com", [only]);
  assert.deepEqual(merged, only);
});

test("an available result with a null priceCents (a registrar bug) never wins over a properly-priced quote", () => {
  const broken: DomainResult = { domain: "example.com", status: "available", premium: false, priceCents: null, renewCents: null };
  const good = available(999);
  assert.equal(mergeCheapest("example.com", [broken, good]).priceCents, 999);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { retailCents } from "../lib/registrar.ts";
import { stripComments } from "./_source-tools.ts";

/**
 * Domains commonly renew at a higher registrar rate than the first-year price
 * (see `Domain.renewPriceCents`'s doc comment in prisma/schema.prisma). The
 * fix is to FREEZE the renewal price/cost at the same moment the first-year
 * price is quoted (registration or transfer-in) — never re-derive it live at
 * renewal time — so what was shown at checkout is what gets charged a year
 * later, even if the platform's markup percentage changes in between.
 *
 * `retailCents` is the one pure function this freeze depends on being called
 * exactly ONCE per quote (not once at quote time and again at renewal time).
 * These tests demonstrate why that matters — recomputing "live" at a
 * different markup produces a DIFFERENT number than what was frozen — and
 * then structurally verify (via a source scan, matching this repo's existing
 * `registrar-leak-guard.test.ts` idiom) that the renewal call sites actually
 * read the frozen columns instead of recomputing from `priceCents`/`costCents`.
 */

const ROOT = join(import.meta.dirname, "..");

test("retailCents applied at two different markups produces two different numbers for the same cost — this is exactly why freezing the result (not just the cost) matters", () => {
  const costCents = 1200; // $12.00 registrar cost
  const frozenAtQuoteTime = retailCents(costCents, 25); // 25% markup when the customer checked out
  const recomputedLaterAtNewMarkup = retailCents(costCents, 40); // owner raised markup to 40% before renewal
  assert.equal(frozenAtQuoteTime, 1500); // $15.00 — what the customer saw and agreed to
  assert.equal(recomputedLaterAtNewMarkup, 2000); // $20.00 — NOT what was shown
  assert.notEqual(frozenAtQuoteTime, recomputedLaterAtNewMarkup);
});

test("a renewal price frozen at quote time is stable no matter how many times it's read back", () => {
  const renewCostCents = 1800;
  const pctAtQuoteTime = 25;
  const renewPriceCentsFrozen = retailCents(renewCostCents, pctAtQuoteTime);
  // Reading the SAME frozen value repeatedly (e.g. the domain detail page, the
  // manual renew button, and the auto-renew sweep all reading Domain.renewPriceCents)
  // must always agree — there is no live re-quote in the loop.
  for (let i = 0; i < 5; i++) {
    assert.equal(renewPriceCentsFrozen, retailCents(renewCostCents, pctAtQuoteTime));
  }
});

/**
 * Structural tripwire (same idiom as registrar-leak-guard.test.ts): the two
 * places that charge a domain renewal — the manual `renewDomainAction` and
 * the automatic `domainAutoRenewSweep` — must read the frozen renewal columns
 * (`renewPriceCents`/`renewCostCents`), not just `domain.priceCents`/`domain.costCents`
 * (the ORIGINAL first-year quote). This guards against a future edit quietly
 * reverting to the bug this pair of columns fixes.
 */
function readSource(relPath: string): string {
  return stripComments(readFileSync(join(ROOT, relPath), "utf8"));
}

test("renewDomainAction reads the frozen renewal price, not just the original registration price", () => {
  const src = readSource("lib/actions-domains.ts");
  assert.match(src, /renewDomainAction/);
  assert.match(
    src,
    /renewPriceCents/,
    "renewDomainAction must read Domain.renewPriceCents (falling back to priceCents), not derive the renewal charge from priceCents alone"
  );
  assert.match(src, /renewCostCents/, "renewDomainAction must tell the registrar the frozen renewal COST, not the original registration cost alone");
});

test("the automatic domain auto-renew sweep reads the frozen renewal price, not just the original registration price", () => {
  const src = readSource("worker/billing.ts");
  assert.match(src, /domainAutoRenewSweep/);
  const sweepStart = src.indexOf("async function domainAutoRenewSweep");
  assert.ok(sweepStart >= 0, "domainAutoRenewSweep must exist in worker/billing.ts");
  const sweepBody = src.slice(sweepStart, sweepStart + 3000);
  assert.match(sweepBody, /renewPriceCents/, "domainAutoRenewSweep must read Domain.renewPriceCents, not just domain.priceCents");
  assert.match(sweepBody, /renewCostCents/, "domainAutoRenewSweep must read Domain.renewCostCents, not just domain.costCents");
});

test("registerDomainCore freezes the renewal price/cost onto the Domain row it creates, from the SAME quote it was given (never a fresh registrar call)", () => {
  const src = readSource("lib/actions-domains.ts");
  const fnStart = src.indexOf("async function registerDomainCore");
  assert.ok(fnStart >= 0);
  const fnBody = src.slice(fnStart, fnStart + 2500);
  assert.match(fnBody, /renewPriceCents:\s*priced\.renewPriceCents/, "registerDomainCore must write priced.renewPriceCents onto the new Domain row");
  assert.match(fnBody, /renewCostCents:\s*priced\.renewCostCents/, "registerDomainCore must write priced.renewCostCents onto the new Domain row");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { XMLParser } from "fast-xml-parser";
import {
  parseCheckResponse,
  parseTldPricingResponse,
  parseDnsHostsResponse,
} from "../lib/registrars/namecheap.ts";

/**
 * Namecheap's API is XML, not JSON — the exact opposite of name.com's. These
 * tests feed REALISTIC sample response bodies (shaped exactly like Namecheap's
 * own official documentation examples for each command — see
 * lib/registrars/namecheap.ts's file header for how those were sourced) through
 * the SAME `fast-xml-parser` config the real client uses, then through the
 * pure parse functions — not a shape this test invented itself. This is the
 * one place a subtly-wrong attribute name (e.g. "YourPrice" vs "Price", or
 * "Domainname" vs "DomainName") would otherwise go unnoticed until a real,
 * paid API call failed in production.
 */

const xmlParser = new XMLParser({ ignoreAttributes: false, attributeNamePrefix: "" });

function parseCommandResponse(xml: string): any {
  const parsed = xmlParser.parse(xml);
  assert.equal(parsed?.ApiResponse?.Status, "OK", "sample fixture must itself be a well-formed OK response");
  return parsed.ApiResponse.CommandResponse;
}

test("namecheap.domains.check: a purchasable name, a taken name, and a premium name in one response", () => {
  // Shaped after Namecheap's own documented example response for
  // namecheap.domains.check (DomainCheckResult attributes: Domain, Available,
  // ErrorNo, Description, IsPremiumName, Premium*Price, IcannFee, EapFee).
  const xml = `<?xml version="1.0" encoding="utf-8"?>
<ApiResponse xmlns="http://api.namecheap.com/xml.response" Status="OK">
  <Errors/>
  <Warnings/>
  <RequestedCommand>namecheap.domains.check</RequestedCommand>
  <CommandResponse Type="namecheap.domains.check">
    <DomainCheckResult Domain="nxeon-free-test.com" Available="true" ErrorNo="0" Description="" IsPremiumName="false" PremiumRegistrationPrice="0" PremiumRenewalPrice="0" PremiumRestorePrice="0" PremiumTransferPrice="0" IcannFee="0" EapFee="0"/>
    <DomainCheckResult Domain="nxeon-taken-test.com" Available="false" ErrorNo="0" Description="" IsPremiumName="false" PremiumRegistrationPrice="0" PremiumRenewalPrice="0" PremiumRestorePrice="0" PremiumTransferPrice="0" IcannFee="0" EapFee="0"/>
    <DomainCheckResult Domain="crypto.com" Available="true" ErrorNo="0" Description="" IsPremiumName="true" PremiumRegistrationPrice="5000.00" PremiumRenewalPrice="5500.00" PremiumRestorePrice="0" PremiumTransferPrice="0" IcannFee="0.18" EapFee="0"/>
  </CommandResponse>
  <Server>SERVER-1</Server>
  <GMTTimeDifference>+5</GMTTimeDifference>
  <ExecutionTime>0.5</ExecutionTime>
</ApiResponse>`;

  const results = parseCheckResponse(parseCommandResponse(xml));
  assert.equal(results.length, 3);

  const free = results.find((r) => r.domain === "nxeon-free-test.com")!;
  assert.equal(free.available, true);
  assert.equal(free.premium, false);
  assert.equal(free.premiumRegisterCents, null); // ordinary names price via users.getPricing, not this response

  const taken = results.find((r) => r.domain === "nxeon-taken-test.com")!;
  assert.equal(taken.available, false);

  const premium = results.find((r) => r.domain === "crypto.com")!;
  assert.equal(premium.available, true);
  assert.equal(premium.premium, true);
  assert.equal(premium.premiumRegisterCents, 500000); // $5000.00 -> integer cents
  assert.equal(premium.premiumRenewCents, 550000); // $5500.00 -> integer cents — renews HIGHER than it registers
});

test("namecheap.users.getPricing: REGISTER and RENEW category pricing for one TLD, YourPrice preferred over the list Price", () => {
  // Shaped after Namecheap's own documented response structure for
  // namecheap.users.getPricing: ProductType > ProductCategory > Product > Price,
  // with Duration/DurationType/Price/RegularPrice/YourPrice/Currency attributes.
  const xml = `<?xml version="1.0" encoding="utf-8"?>
<ApiResponse xmlns="http://api.namecheap.com/xml.response" Status="OK">
  <Errors/>
  <RequestedCommand>namecheap.users.getPricing</RequestedCommand>
  <CommandResponse Type="namecheap.users.getPricing">
    <UserGetPricingResult>
      <ProductType Name="DOMAIN">
        <ProductCategory Name="REGISTER">
          <Product Name="com">
            <Price Duration="1" DurationType="YEAR" Price="10.98" RegularPrice="10.98" YourPrice="8.88" CouponPrice="" Currency="USD"/>
            <Price Duration="2" DurationType="YEAR" Price="21.96" RegularPrice="21.96" YourPrice="17.76" CouponPrice="" Currency="USD"/>
          </Product>
          <Product Name="net">
            <Price Duration="1" DurationType="YEAR" Price="12.98" RegularPrice="12.98" YourPrice="11.28" CouponPrice="" Currency="USD"/>
          </Product>
        </ProductCategory>
        <ProductCategory Name="RENEW">
          <Product Name="com">
            <Price Duration="1" DurationType="YEAR" Price="15.98" RegularPrice="15.98" YourPrice="13.98" CouponPrice="" Currency="USD"/>
          </Product>
          <Product Name="net">
            <Price Duration="1" DurationType="YEAR" Price="16.98" RegularPrice="16.98" YourPrice="15.48" CouponPrice="" Currency="USD"/>
          </Product>
        </ProductCategory>
      </ProductType>
    </UserGetPricingResult>
  </CommandResponse>
  <Server>SERVER-1</Server>
  <GMTTimeDifference>+5</GMTTimeDifference>
  <ExecutionTime>1.1</ExecutionTime>
</ApiResponse>`;

  const map = parseTldPricingResponse(parseCommandResponse(xml));
  // Both REGISTER and RENEW categories collapse into one map keyed by TLD —
  // this fixture alone can't distinguish which category a value came from
  // (that's what the two separate REGISTER/RENEW `nc()` calls are for in the
  // real client); what matters here is the 1-year YourPrice is picked correctly
  // and the 2-year row for "com" is correctly ignored in favor of Duration="1".
  assert.equal(map.get("com"), 1398); // last one parsed wins when a TLD appears in both categories: RENEW's 13.98
  assert.equal(map.get("net"), 1548);
});

