test("namecheap.domains.dns.getHosts: apex '@' host normalizes to the empty host name lib/registrar.ts's DomainCheck/DnsRecord shape expects", () => {
  // Shaped after Namecheap's own documented example response for
  // namecheap.domains.dns.getHosts (Host attributes: HostId, Name, Type,
  // Address, MXPref, TTL).
  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<ApiResponse xmlns="http://api.namecheap.com/xml.response" Status="OK">
  <Errors />
  <RequestedCommand>namecheap.domains.dns.getHosts</RequestedCommand>
  <CommandResponse Type="namecheap.domains.dns.getHosts">
    <DomainDNSGetHostsResult Domain="example.com" IsUsingOurDNS="true">
      <Host HostId="12" Name="@" Type="A" Address="1.2.3.4" MXPref="10" TTL="1800" />
      <Host HostId="14" Name="www" Type="A" Address="122.23.3.7" MXPref="10" TTL="1800" />
      <Host HostId="16" Name="@" Type="MX" Address="mail.example.com" MXPref="10" TTL="1800" />
    </DomainDNSGetHostsResult>
  </CommandResponse>
  <Server>SERVER-NAME</Server>
  <GMTTimeDifference>+5</GMTTimeDifference>
  <ExecutionTime>32.76</ExecutionTime>
</ApiResponse>`;

  const records = parseDnsHostsResponse(parseCommandResponse(xml));
  assert.equal(records.length, 3);
  const apexA = records.find((r) => r.type === "A" && r.host === "");
  assert.ok(apexA, "the apex '@' host must normalize to an empty host string, matching name.com's own apex convention");
  assert.equal(apexA!.answer, "1.2.3.4");
  assert.equal(apexA!.id, "12");
  const www = records.find((r) => r.host === "www")!;
  assert.equal(www.answer, "122.23.3.7");
  const mx = records.find((r) => r.type === "MX")!;
  assert.equal(mx.priority, 10);
});

