/**
 * Merge one domain's per-registrar results into the single result the
 * customer sees. Pure and exported for testing — this is the one place
 * "which registrar's price wins" is decided.
 *
 *   - At least one "available" (with a price) -> "available", cheapest price
 *     wins. This takes priority over a DISAGREEING "taken" from another
 *     registrar — registries can be out of sync with each other by minutes to
 *     hours, and the multi-registrar plan's own recommendation for this exact
 *     case (see its Open Questions) is "available if any configured registrar
 *     says available with a price; taken only if none do" — a false "taken"
 *     costs nothing, a false "available" that then fails to register is worse.
 *   - Else at least one "taken" -> "taken".
 *   - Else -> "unknown" (every registrar was down/throttled/unconfigured) —
 *     never fabricated as available or taken.
 *
 * A genuine available/taken disagreement between registrars is logged (not
 * silently resolved) so ops can see how often it actually happens.
 *
 * `results` must be non-empty; each entry ideally already carries `domain`
 * matching the domain being merged (not checked here — the caller guarantees it).
 */
export function mergeCheapest(domain: string, results: DomainResult[]): DomainResult {
  const available = results.filter((r) => r.status === "available" && r.priceCents !== null);
  const anyTaken = results.some((r) => r.status === "taken");
  if (available.length > 0) {
    if (anyTaken) {
      console.error(`[registrar] availability disagreement for ${domain}: at least one registrar says available, another says taken — showing available`);
    }
    return available.reduce((best, r) => (r.priceCents! < best.priceCents! ? r : best));
  }
  if (anyTaken) {
    // Prefer a "taken" entry's own shape (e.g. its `premium` flag) over a synthesized one.
    return results.find((r) => r.status === "taken") ?? { domain, status: "taken", premium: false, priceCents: null, renewCents: null };
  }
  return unknown(domain);
}
